  false,
  '{"servingSize":"1 portion (~382g)","calories":460,"energyKj":1925,"protein":32,"carbohydrates":28,"sugar":4,"fiber":4,"totalFat":17,"saturatedFat":6,"sodium":644}'::jsonb
),
(
  'turmeric-cauliflower-tahini-bowl',
  'turmeric-cauliflower-tahini-bowl',
  'Golden Turmeric Roasted Cauliflower & Crispy Chickpea Bowl',
  'Caramelized spiced florets over warm farro, lemony garlic tahini & pomegranate jewels',
  'A vibrant Mediterranean grain bowl celebrating plant-powered crunch and brightness. Whole cauliflower florets and chickpeas tossed in turmeric, smoked paprika, and sumac, roasted till crispy-edged, layered over warm ancient grains with a velvety garlic tahini drizzle.',
  'Vegan',
  'Eastern Mediterranean / Levantine',
  '10 mins',
  10,
  '25 mins',
  25,
  '35 mins',
  4,
  'Easy',
  4.87,
  142,
  420,
  '"Vegan","Nutritious","Meal Prep","High-Fiber","Eastern Mediterranean / Levantine","Vegetarian","Gluten-Free","Dairy-Free","Nut-Free"',
  '"Large rimmed baking sheet","Parchment paper","Small whisk or blender for tahini"',
  '[{"name":"Cauliflower head, cut into bite-sized florets","amount":1,"unit":"large head","notes":"Thoroughly dry","category":"Produce"},{"name":"Cooked chickpeas (garbanzo beans), rinsed & dried","amount":1.5,"unit":"cups","notes":"Canned or cooked from dry","category":"Pantry"},{"name":"Ground golden turmeric","amount":1.5,"unit":"tsp","notes":"Vibrant anti-inflammatory spice","category":"Spices"},{"name":"Ground cumin","amount":1,"unit":"tsp","notes":"Earthy spice","category":"Spices"},{"name":"Smoked paprika","amount":1,"unit":"tsp","notes":"Sweet smoke","category":"Spices"},{"name":"Extra virgin olive oil","amount":3,"unit":"tbsp","notes":"For roasting","category":"Pantry"},{"name":"Cooked farro or quinoa","amount":3,"unit":"cups","notes":"Fluffy and warm","category":"Pantry"},{"name":"Pure sesame tahini paste","amount":0.33,"unit":"cup","notes":"Stir jar well before measuring","category":"Pantry"},{"name":"Fresh lemon juice","amount":3,"unit":"tbsp","notes":"For dressing","category":"Produce"},{"name":"Garlic clove, grated","amount":1,"unit":"small","notes":"Microplaned","category":"Produce"},{"name":"Ice cold water","amount":4,"unit":"tbsp","notes":"To emulsify tahini to pale ivory","category":"Pantry"},{"name":"Pomegranate arils","amount":0.5,"unit":"cup","notes":"Sweet-tart burst","category":"Produce"},{"name":"Fresh mint and parsley leaves","amount":0.5,"unit":"cup","notes":"Roughly torn","category":"Produce"}]'::jsonb,
  '[{"step":1,"title":"Toss Spiced Florets & Chickpeas","instruction":"Preheat oven to 425°F (220°C). On a large parchment-lined baking sheet, combine cauliflower florets and dried chickpeas. Drizzle with olive oil. Sprinkle turmeric, cumin, smoked paprika, 1 tsp kosher salt, and black pepper. Toss with hands until evenly coated in bright golden yellow.","time":"5 mins","temp":"Preheat 425°F (220°C)","visualCue":"Every floret and chickpea glows vibrant saffron gold."},{"step":2,"title":"Roast to Blistered Caramelization","instruction":"Spread florets in a single layer with flat sides facing down. Roast for 22-25 minutes, flipping once halfway, until cauliflower edges are deeply browned and crispy, and chickpeas are pleasantly crunchy.","time":"25 mins","temp":"425°F (220°C)","visualCue":"Deep bronze charred tips on florets with irresistible roasted nutty scent."},{"step":3,"title":"Whisk the Lemony Tahini Dressing","instruction":"In a bowl, whisk tahini paste, lemon juice, grated garlic, and 1/2 tsp salt. It will seize up and turn paste-like. Gradually whisk in ice cold water tablespoon by tablespoon until it magically transforms into a pale, velvety, pourable dressing.","time":"3 mins","temp":"Room temp","visualCue":"Changes from dark stiff paste to silky, pale ivory ribbon dressing."},{"step":4,"title":"Assemble Grain Bowls","instruction":"Divide warm farro or quinoa among 4 wide bowls. Heap with golden roasted turmeric cauliflower and crunchy spiced chickpeas.","time":"2 mins","temp":"Warm","visualCue":"Gorgeous contrast between nutty brown farro and glowing yellow cauliflower."},{"step":5,"title":"Garnish & Drizzle","instruction":"Drizzle generously with lemon tahini sauce. Scatter ruby red pomegranate seeds, fresh mint, parsley, and a dusting of sumac. Serve warm or room temperature.","time":"2 mins","temp":"Plating","visualCue":"A food magazine-worthy bowl bursting with ruby, emerald, and saffron colors."}]'::jsonb,
  '"Place cauliflower flat side down directly against the hot baking sheet — this maximizes surface contact for deep golden caramelization.","Ice cold water is essential when making tahini sauce; warm water makes it separate, whereas cold water creates an airy whipped emulsion.","Ensure chickpeas are patted completely dry with a paper towel; moisture causes steaming instead of crisping."',
  '[{"original":"Farro","alternative":"Quinoa, brown rice, or cauliflower rice","notes":"Use quinoa for 100% gluten-free meal."},{"original":"Pomegranate seeds","alternative":"Dried cranberries or golden raisins","notes":"Provides sweet-tart chew."}]'::jsonb,
  '[{"mistake":"Crowding the baking sheet","remedy":"If crowded, vegetables will steam and turn soggy. Use two pans if needed."},{"mistake":"Panicking when tahini seizes","remedy":"Tahini always stiffens when citrus is added; just keep whisking in cold water and it will smooth out."}]'::jsonb,
  '"Sesame (Tahini)","Gluten (if using Farro; swap with Quinoa)"',
  'Turmeric stains wooden spoons and porous countertops; wipe up drips promptly.',
  'Ideal for meal prep! Keep components in separate airtight containers in the fridge for up to 5 days.',
  'https://images.unsplash.com/photo-1540420773420-3366772f4999?auto=format&fit=crop&w=1200&q=80',
  false,
  '{"servingSize":"1 portion (~354g)","calories":420,"energyKj":1757,"protein":15,"carbohydrates":46,"sugar":6,"fiber":6,"totalFat":15,"saturatedFat":5,"sodium":504}'::jsonb
),
(
  'classic-french-lemon-tart',
  'classic-french-lemon-tart',
  'Classic French Tarte au Citron (Meyer Lemon Tart)',
  'Crisp sweet sablée pastry filled with silky, tart Meyer lemon curd & powdered sugar',
  'The benchmark of Parisian pastry shops. A buttery, crisp pâte sablée crust baked golden, filled with an unctuous, jewel-toned Meyer lemon curd made with fresh zest, farm eggs, and emulsified European butter, baked gently to a mirror-like finish.',
  'Desserts',
  'French Haute Patisserie',
  '30 mins',
  30,
  '35 mins',
  35,
  '65 mins',
  8,
  'Hard',
  4.98,
  189,
  390,
  '"French Classic","Baking Mastery","Vegetarian","Showstopper","French Haute Patisserie","French","Dessert","Desserts","Eggetarian","Nut-Free"',
  '"9-inch fluted tart pan with removable bottom","Pie weights or dry beans","Fine mesh sieve","Microplane zester","Immersion blender or wire whisk"',
  '[{"name":"Unbleached all-purpose flour","amount":1.5,"unit":"cups","notes":"Pastry flour or AP flour","category":"Pantry"},{"name":"Powdered confectioners'' sugar","amount":0.5,"unit":"cup","notes":"For tender melt-in-mouth crust","category":"Pantry"},{"name":"Unsalted European butter (cold, cubed)","amount":115,"unit":"g","notes":"1 stick, chilled","category":"Dairy"},{"name":"Egg yolk","amount":1,"unit":"yolk","notes":"Binds the sablée dough","category":"Dairy"},{"name":"Ice water","amount":1,"unit":"tbsp","notes":"As needed to bring dough together","category":"Pantry"},{"name":"Fresh Meyer lemons (or standard Eureka)","amount":5,"unit":"lemons","notes":"Zest of 3, strained juice of 5 (about 3/4 cup)","category":"Produce"},{"name":"Granulated sugar","amount":0.75,"unit":"cup","notes":"Curd sweetener","category":"Pantry"},{"name":"Large eggs (room temp)","amount":4,"unit":"eggs","notes":"Whisked smooth","category":"Dairy"},{"name":"Unsalted butter (at room temp, cubed)","amount":100,"unit":"g","notes":"For curd emulsion","category":"Dairy"},{"name":"Fine sea salt","amount":0.25,"unit":"tsp","notes":"Enhances citrus flavor","category":"Pantry"}]'::jsonb,
  '[{"step":1,"title":"Make Pâte Sablée Crust","instruction":"Pulse flour, powdered sugar, and pinch of salt in food processor. Add cold cubed butter; pulse until mixture resembles coarse breadcrumbs. Add egg yolk and ice water; pulse just until dough comes together. Form into a flat disc, wrap in plastic, and chill for 45 mins.","time":"15 mins + chill","temp":"Refrigerated (38°F / 3°C)","visualCue":"Dough holds together when pressed without sticking to fingers."},{"step":2,"title":"Blind Bake the Tart Shell","instruction":"Roll dough on lightly floured surface to 1/8-inch thickness. Line a 9-inch tart pan with removable bottom. Prick base with fork. Freeze for 15 mins. Line with parchment paper, fill with pie weights, and bake at 350°F (175°C) for 18 mins. Remove weights and bake 8 more mins until pale golden. Cool completely.","time":"26 mins","temp":"350°F (175°C)","visualCue":"Crust is dry, crisp, and biscuit-colored with no wet spots."},{"step":3,"title":"Cook the Velvety Lemon Curd","instruction":"In a saucepan over medium-low heat, whisk lemon juice, lemon zest, sugar, and whole eggs. Whisk continuously for 8-10 minutes until mixture thickens to a glossy pudding consistency (170°F / 77°C). Do not boil or eggs will scramble.","time":"10 mins","temp":"Medium-low (170°F / 77°C)","visualCue":"Curd coats the back of a spoon and leaves a clear line when finger is drawn across."},{"step":4,"title":"Strain & Butter Emulsion","instruction":"Strain hot lemon curd through a fine-mesh sieve into a bowl to catch zest and cooked chalazae. Cool to 120°F (warm to touch). Using an immersion blender or whisk, incorporate the room-temperature butter one cube at a time until lustrous and glossy.","time":"5 mins","temp":"Warm","visualCue":"Curd becomes pale yellow, silk-smooth, and glossy like liquid satin."},{"step":5,"title":"Fill, Chill & Set","instruction":"Pour the warm curd into the cooled tart shell. Smooth top with an offset spatula. Bake at 325°F for 6 minutes just to set the surface mirror. Cool to room temp, then chill in refrigerator for at least 3 hours. Dust lightly with powdered sugar before slicing.","time":"6 mins + chill","temp":"325°F (165°C)","visualCue":"A glassy, mirror-smooth yellow surface that slices cleanly like chilled custard."}]'::jsonb,
  '"Powdered sugar in the pastry prevents gluten development, giving you the crumbly, shortbread texture of true French sablée.","Straining the lemon curd through a fine mesh sieve is mandatory for professional patisserie smoothness.","Blending in butter when the curd cools to 120°F creates a stable micro-emulsion instead of melting into oily butter fat."',
  '[{"original":"Meyer lemons","alternative":"Regular lemons + 2 tbsp fresh orange juice","notes":"Mimics the floral sweetness of Meyer lemons."},{"original":"Pâte sablée","alternative":"Crushed Graham cracker or Speculoos butter crust","notes":"Saves time if you want a no-roll crust."}]'::jsonb,
  '[{"mistake":"Boiling the curd over high heat","remedy":"Direct fierce heat scrambles eggs into sweet egg drop soup. Gentle whisking is key."},{"mistake":"Slicing before properly chilled","remedy":"Curd requires minimum 3 hours in fridge to firm up for knife-clean wedges."}]'::jsonb,
  '"Eggs","Dairy","Gluten"',
  'Use oven mitts when removing hot pie weights from the blind-baked shell.',
  'Store in refrigerator up to 4 days. Best eaten cold.',
  'https://images.unsplash.com/photo-1519869325930-281384150729?auto=format&fit=crop&w=1200&q=80',
  false,
  '{"servingSize":"1 portion (~333g)","calories":390,"energyKj":1632,"protein":10,"carbohydrates":51,"sugar":38,"fiber":3,"totalFat":18,"saturatedFat":11,"sodium":137}'::jsonb
),
(
  'japanese-miso-glazed-eggplant',
  'japanese-miso-glazed-eggplant',
  'Caramelized Japanese Miso Eggplant (Nasu Dengaku)',
  'Tender cross-hatched Japanese eggplant with sweet caramelized red miso glaze & toasted sesame',
  'An iconic Japanese izakaya favorite. Slender Japanese eggplants scored in diamond lattices, pan-seared until creamy-soft, brushed with a luxurious glaze of red miso, mirin, sake, and raw cane sugar, then broiled until bubbly and caramelized.',
  'Asian',
  'Japanese',
  '8 mins',
  8,
  '17 mins',
  17,
  '25 mins',
  4,
  'Easy',
  4.91,
  167,
  220,
  '"Vegan","Quick Meals","Gluten-Free","Izakaya Style","Japanese","Vegetarian","Asian","Jain-Friendly","Nut-Free","High-Protein","Low-Sugar"',
  '"Large oven-safe skillet or baking sheet","Sharp chef's knife for diamond scoring","Pastry brush","Small saucepan for glaze"',
  '[{"name":"Japanese or Chinese eggplants (slender and long)","amount":3,"unit":"medium","notes":"Halved lengthwise","category":"Produce"},{"name":"Sesame oil + neutral oil","amount":2,"unit":"tbsp","notes":"For pan-frying","category":"Pantry"},{"name":"Red or awase miso paste","amount":3,"unit":"tbsp","notes":"Fermented soybean paste","category":"Pantry"},{"name":"Mirin (sweet Japanese cooking wine)","amount":2,"unit":"tbsp","notes":"Adds gloss and sweetness","category":"Pantry"},{"name":"Japanese cooking sake","amount":1.5,"unit":"tbsp","notes":"Deglazes and balances","category":"Pantry"},{"name":"Cane sugar or maple syrup","amount":1.5,"unit":"tbsp","notes":"Balances savory miso","category":"Pantry"},{"name":"Grated fresh ginger","amount":1,"unit":"tsp","notes":"Adds zesty freshness","category":"Produce"},{"name":"Toasted white and black sesame seeds","amount":1,"unit":"tbsp","notes":"For garnish crunch","category":"Pantry"},{"name":"Scallions, sliced razor thin","amount":2,"unit":"stalks","notes":"Soaked in ice water to curl","category":"Produce"}]'::jsonb,
  '[{"step":1,"title":"Score the Eggplants","instruction":"Halve eggplants lengthwise. Using a sharp knife tip, score the flesh in a diagonal crosshatch diamond pattern, cutting deep without piercing through the purple skin.","time":"4 mins","temp":"Room temp","visualCue":"Neat diamond facets that allow heat and savory glaze to penetrate to the center."},{"step":2,"title":"Whisk the Sweet Miso Glaze","instruction":"In a small saucepan over low heat, whisk together miso paste, mirin, sake, sugar, and grated ginger. Simmer gently for 2-3 minutes until sugar is fully dissolved and glaze coats the whisk.","time":"3 mins","temp":"Low heat","visualCue":"A thick, shiny caramel-brown glaze with sweet fermented aroma."},{"step":3,"title":"Pan-Sear Eggplants Soft","instruction":"Heat oils in a skillet over medium-high heat. Place eggplants flesh side down. Cook undisturbed for 5 minutes until browned and softened. Flip, cover with lid, and cook skin side down for 4 minutes until flesh yields completely to gentle pressure.","time":"9 mins","temp":"Medium-high (350°F / 175°C)","visualCue":"Flesh becomes golden, translucent, and custardy soft."},{"step":4,"title":"Glaze & Caramelize Under Broiler","instruction":"Transfer eggplants skin side down onto a baking sheet. Generously brush top scored flesh with the warm miso glaze. Broil on high for 2 to 3 minutes until glaze is bubbling furiously and lightly charred at edges.","time":"3 mins","temp":"Broil High (500°F / 260°C)","visualCue":"Glaze bubbles into glossy, caramelized amber pearls with scorched roasted tips."},{"step":5,"title":"Garnish & Enjoy","instruction":"Gently transfer to a platter. Sprinkle with toasted sesame seeds and curly scallion ribbons. Serve hot with steamed rice.","time":"1 min","temp":"Plating","visualCue":"A dramatic presentation with glistening dark miso against bright green scallions."}]'::jsonb,
  '"Diamond scoring is essential: eggplant behaves like a sponge and scoring ensures the center absorbs seasonings evenly.","Broil with the oven door cracked slightly if using an electric oven; keep your eye glued to the pan as sugar burns in seconds.","Japanese eggplants have paper-thin skin and fewer seeds than globe eggplants, making them ideal for this dish."',
  '[{"original":"Japanese eggplant","alternative":"Small Italian baby eggplants or zucchini halves","notes":"Zucchini needs slightly less cooking time."},{"original":"Red miso","alternative":"White (Shiro) miso","notes":"Yields a milder, sweeter glaze."}]'::jsonb,
  '[{"mistake":"Under-cooking the eggplant flesh before glazing","remedy":"Eggplant must be custardy soft before the broiler; the broiler only caramelizes the top."},{"mistake":"Piercing the purple skin while scoring","remedy":"Cut only 2/3 of the way down; intact skin holds the custardy flesh like a little boat."}]'::jsonb,
  '"Soy","Sesame"',
  'Do not leave the broiler unattended — the high sugar content caramelizes quickly.',
  'Best fresh. Leftovers can be reheated in a 350°F oven for 6 minutes.',
  'https://images.unsplash.com/photo-1540420773420-3366772f4999?auto=format&fit=crop&w=1000&q=80',
  false,
  '{"servingSize":"1 portion (~214g)","calories":220,"energyKj":920,"protein":26,"carbohydrates":13,"sugar":2,"fiber":2,"totalFat":8,"saturatedFat":3,"sodium":308}'::jsonb
),
(
  'south-indian-masala-dosa',
  'south-indian-masala-dosa',
  'Crispy South Indian Masala Dosa with Spiced Potato Filling',
  'Golden lacy fermented rice-lentil crepe wrapped around mustard-scented potato masala',
  'The undisputed crown jewel of South Indian breakfast culinary art. Naturally fermented rice and urad dal batter swirled paper-thin on a seasoned iron tawa, roasted crisp with ghee, and folded around a fragrant spiced potato filling alongside fresh coconut chutney.',
  'Indian',
  'South Indian (Tamil Nadu / Karnataka)',
  '20 mins',
  20,
  '30 mins',
  30,
  '50 mins',
  4,
  'Hard',
  4.97,
  330,
  340,
  '"Vegan","Gluten-Free","Street Food Legend","Crispy Perfection","South Indian (Tamil Nadu / Karnataka)","Breakfast","Vegetarian","Indian","Low-Sugar"',
  '"Flat cast iron tawa or heavy crepe pan","Round bottom ladle (for spiraling batter)","Thin flat metal spatula (dosa thiruppi)","Potato masher"',
  '[{"name":"Fermented Dosa batter (rice & urad dal)","amount":3,"unit":"cups","notes":"Properly fermented, bubbly and pouring consistency","category":"Pantry"},{"name":"Yukon gold potatoes, boiled and peeled","amount":4,"unit":"medium","notes":"Roughly crushed with fork","category":"Produce"},{"name":"Ghee or sesame/peanut oil (for vegan)","amount":3,"unit":"tbsp","notes":"Drizzled along edges for crispiness","category":"Pantry"},{"name":"Mustard seeds","amount":1,"unit":"tsp","notes":"Tempered until popping","category":"Spices"},{"name":"Cumin seeds","amount":0.5,"unit":"tsp","notes":"Tempering spice","category":"Spices"},{"name":"Chana dal (split bengal gram)","amount":1,"unit":"tbsp","notes":"Fried crunchy for texture","category":"Pantry"},{"name":"Fresh curry leaves","amount":12,"unit":"leaves","notes":"Bruised to release oil","category":"Produce"},{"name":"Green chilies, finely sliced","amount":2,"unit":"chilies","notes":"Adjust for spice","category":"Produce"},{"name":"Ginger, finely minced","amount":1,"unit":"tbsp","notes":"Fresh ginger","category":"Produce"},{"name":"Yellow onion, thinly sliced","amount":1,"unit":"large","notes":"Cooked translucent","category":"Produce"},{"name":"Ground turmeric","amount":0.5,"unit":"tsp","notes":"Gives potato filling its warm yellow color","category":"Spices"},{"name":"Fresh grated coconut chutney","amount":1,"unit":"cup","notes":"For dipping alongside sambar","category":"Pantry"}]'::jsonb,
  '[{"step":1,"title":"Temper Spices for Potato Masala","instruction":"Heat 1 tbsp oil in a pan over medium heat. Add mustard seeds and let them pop merrily. Add chana dal, cumin seeds, and curry leaves. Sauté until chana dal turns golden brown and crunchy.","time":"2 mins","temp":"Medium heat","visualCue":"Mustard seeds crackle enthusiastically; curry leaves turn translucent green."},{"step":2,"title":"Sauté Onions & Cook Potato Masala","instruction":"Add sliced onions, minced ginger, and green chilies. Cook for 5 minutes until onions are soft and translucent (do not brown). Add turmeric and salt, then stir in roughly crushed boiled potatoes and 1/3 cup water. Simmer for 3 minutes until moist and cohesive. Keep warm.","time":"8 mins","temp":"Medium-low heat","visualCue":"Vibrant yellow spiced potato mash that holds its shape gently."},{"step":3,"title":"Heat & Season the Tawa","instruction":"Heat cast iron tawa until very hot. Sprinkle water droplets; they should sizzle and evaporate immediately. Wipe down with half a cut onion dipped in oil to create a natural non-stick surface.","time":"2 mins","temp":"Medium-high heat (375°F / 190°C)","visualCue":"Water beads skitter across surface like dancing mercury."},{"step":4,"title":"The Spiral Ladle Technique","instruction":"Pour a generous ladle of batter (about 1/3 cup) into center of tawa. Immediately place back of ladle in center and spread in quick, continuous outward concentric spirals towards edges to form a thin circular crepe.","time":"1 min","temp":"Medium-high heat","visualCue":"Batter sets into tiny lacy pores across the crepe within 15 seconds."},{"step":5,"title":"Roast to Amber Crisp & Fold","instruction":"Drizzle 1 tsp ghee around edges and over center. Roast on medium heat for 2-3 minutes without flipping until underside is deep amber golden and edges naturally lift from pan. Spoon 3 tbsp warm potato masala across center. Fold both sides over like a scroll. Serve sizzling with coconut chutney.","time":"3 mins","temp":"Medium heat","visualCue":"Shatteringly crisp golden-brown crepe wrapping the soft yellow potato interior."}]'::jsonb,
  '"Wiping the tawa with half a raw onion before spreading batter is the traditional secret for flawless release without sticking.","If the pan is too hot, batter will clump onto the ladle; splash water droplets to bring temperature down before each dosa.","A drizzle of real ghee along the rim turns the edges into paper-thin, crispy gold."',
  '[{"original":"Dosa batter","alternative":"Store-bought fresh dosa batter (available at Indian grocers)","notes":"Ensure it is at room temperature before pouring."},{"original":"Ghee","alternative":"Cold-pressed sesame or coconut oil","notes":"Keeps recipe strictly 100% vegan."}]'::jsonb,
  '[{"mistake":"Trying to spread cold batter straight from the fridge","remedy":"Cold batter tears and drags on the tawa; always bring to room temp."},{"mistake":"Flipping the dosa","remedy":"Authentic paper-thin masala dosa is cooked on one side only until roasted through."}]'::jsonb,
  '"Dairy (if using Ghee; can be substituted for Vegan)"',
  'Cast iron tawa stays hot for a long time; use caution around edges.',
  'Dosas must be eaten hot off the tawa. Leftover potato masala keeps in fridge for up to 4 days.',
  'https://images.unsplash.com/photo-1668236543090-82eba5ee5976?auto=format&fit=crop&w=1200&q=80',
  false,
  '{"servingSize":"1 portion (~298g)","calories":340,"energyKj":1423,"protein":12,"carbohydrates":37,"sugar":4,"fiber":5,"totalFat":12,"saturatedFat":4,"sodium":408}'::jsonb
),
(
  'dal-makhani-bukhara-style',
  'dal-makhani-bukhara-style',
  'Old Delhi 24-Hour Dal Makhani',
  'Slow-simmered whole black urad dal & kidney beans with churned butter and cream',
  'An iconic Punjabi classic. Whole black lentils and kidney beans are slow-cooked overnight with vine-ripened tomatoes, fresh ginger, butter, and fragrant dried fenugreek leaves until deeply savory and velvety smooth.',
