  '[{"step":1,"title":"Boil Chickpeas with Tea Infusion","instruction":"Pressure cook chickpeas with water, 2 tea bags, bay leaf, and 1 tsp salt for 5 whistles. Discard tea bags and save dark broth.","time":"25 mins","temp":"High pressure","visualCue":"Chickpeas turn dark mahogany and mash softly."},{"step":2,"title":"Knead Bhature Dough","instruction":"Mix flour, semolina, yogurt, baking powder, sugar, and warm water. Knead into soft dough and rest under damp cloth 2 hours.","time":"10 mins + rest","temp":"Room temp","visualCue":"Dough becomes elastic and smooth."},{"step":3,"title":"Simmer Chole Masala","instruction":"Heat ghee in a pot. Add ginger juliennes, green chilies, anardana, and ground spices. Add boiled chickpeas and 1 cup broth. Simmer 15 mins.","time":"15 mins","temp":"Medium heat","visualCue":"Thick, dark spicy coating around chickpeas."},{"step":4,"title":"Puff Balloon Bhature","instruction":"Roll dough into ovals. Slide into 375°F oil, pressing gently with slotted spoon until it puffs into a giant ball. Flip and fry 20 seconds.","time":"5 mins","temp":"375°F (190°C)","visualCue":"Golden brown inflated balloon with crispy shell."}]'::jsonb,
