  '[{"step":1,"title":"Steam Greens","instruction":"Simmer greens with garlic, ginger, chilies, and 1 cup water for 30 minutes until fully tender.","time":"30 mins","temp":"Medium heat","visualCue":"Greens wilt and turn deep olive green."},{"step":2,"title":"Whisk in Cornmeal","instruction":"Pulse coarsely. Whisk 3 tbsp cornmeal with water and pour into greens. Simmer 10 minutes until glossy and thick.","time":"10 mins","temp":"Low heat","visualCue":"Velvety, emulsified rustic saag."},{"step":3,"title":"Garlic Ghee Tadka","instruction":"Brown garlic slices and dried chilies in hot ghee. Pour sizzling over saag.","time":"3 mins","temp":"Medium-high heat","visualCue":"Aromatic sizzle with toasted garlic fragrance."},{"step":4,"title":"Roast Makki Roti","instruction":"Knead cornmeal with warm water. Pat into round disks and roast on hot tawa with ghee until golden speckled.","time":"10 mins","temp":"Medium-high heat","visualCue":"Golden brown spots with crisp toasted rim."}]'::jsonb,
