  '[{"step":1,"title":"First Acid Rub","instruction":"Rub chicken with lime juice, 1 tbsp ginger-garlic, and salt. Rest 15 mins to tenderize fibers.","time":"15 mins","temp":"Room temp","visualCue":"Chicken absorbs lemon acid evenly."},{"step":2,"title":"Second Spiced Yogurt Coat","instruction":"Whisk hung yogurt, mustard oil, Kashmiri chili, garam masala, and kasuri methi. Coat deeply into every slash. Chill 2 hours.","time":"10 mins + chill","temp":"Refrigerated","visualCue":"Opaque, fragrant crimson marinade clinging to meat."},{"step":3,"title":"Roast on Wire Rack","instruction":"Roast at 450°F on a wire rack for 20 minutes, basting with melted butter once.","time":"20 mins","temp":"450°F (230°C)","visualCue":"Juices run clear and surface starts caramelizing."},{"step":4,"title":"Broil for Tandoor Char","instruction":"Broil on high for 4-5 minutes until edges blister into dark smoky spots. Dust with chaat masala.","time":"5 mins","temp":"Broil High","visualCue":"Signature charred mahogany blisters with tender juicy interior."}]'::jsonb,
