  '[{"step":1,"title":"Shape Stuffed Koftas","instruction":"Knead paneer, potatoes, cornstarch, and salt into smooth dough. Form balls, stuff center with nuts and raisins, and roll into smooth crack-free dumplings.","time":"15 mins","temp":"Room temp","visualCue":"Smooth surface without any cracks."},{"step":2,"title":"Golden Crisp Frying","instruction":"Fry dumplings in 350°F oil until evenly golden crisp all over. Drain on paper towels.","time":"8 mins","temp":"350°F (175°C)","visualCue":"Delicate golden amber crust."},{"step":3,"title":"Silky Cashew Gravy","instruction":"Blend soaked cashews and boiled onions until silk-smooth. Simmer with butter, cardamom, and cream for 10 mins.","time":"15 mins","temp":"Low simmer","visualCue":"Lustrous ivory gravy with delicate aroma."},{"step":4,"title":"Assemble to Serve","instruction":"Ladle warm sauce into a bowl and arrange hot crispy koftas on top just before serving.","time":"2 mins","temp":"Warm","visualCue":"Dumplings stay crisp while dipping in sauce."}]'::jsonb,
