  '[{"step":1,"title":"Prepare Spiced Potato Bhaji","instruction":"Heat 1 tbsp oil. Temper mustard seeds, urad dal, curry leaves, and green chilies. Sauté sliced onions until translucent. Stir in turmeric, salt, and mashed potatoes with a splash of water.","time":"8 mins","temp":"Medium heat","visualCue":"Aromatic, moist yellow potato filling."},{"step":2,"title":"Spread Dosa on Hot Tawa","instruction":"Pour a ladle of batter onto center of hot cast iron tawa. Swirl outward in spiral motion to create a paper-thin crepe.","time":"1 min","temp":"Medium-high heat","visualCue":"Batter forms delicate lacy holes and sets."},{"step":3,"title":"Layer Mysore Red Chutney & Ghee","instruction":"Drizzle ghee around the edges. Spread 1 tbsp red garlic chutney across the center. Roast until bottom turns rich golden brown.","time":"2 mins","temp":"Medium heat","visualCue":"Deep reddish-gold underside releasing easily from pan."},{"step":4,"title":"Fill & Fold","instruction":"Spoon warm potato bhaji down center. Fold into a crisp cylinder and serve immediately with fresh coconut chutney and piping hot sambar.","time":"1 min","temp":"Off heat","visualCue":"Shatteringly crisp golden crepe wrapping soft potatoes."}]'::jsonb,
