  '"Pressure cooker or deep Dutch oven","Small tadka pan"',
  '[{"name":"Sona Masoori or Ponni rice","amount":1,"unit":"cup","notes":"Washed & drained","category":"Pantry"},{"name":"Toor dal (split pigeon peas)","amount":0.75,"unit":"cup","notes":"Soaked 30 mins","category":"Pantry"},{"name":"Mixed vegetables (shallots, carrots, beans, pumpkin)","amount":300,"unit":"g","notes":"Diced","category":"Produce"},{"name":"Bisi bele bath powder","amount":2.5,"unit":"tbsp","notes":"Freshly roasted spice blend","category":"Spices"},{"name":"Tamarind extract","amount":3,"unit":"tbsp","notes":"Thick pulp","category":"Pantry"},{"name":"Jaggery (gur)","amount":1,"unit":"tbsp","notes":"Balances tamarind tang","category":"Pantry"},{"name":"Desi ghee & whole cashews","amount":3,"unit":"tbsp","notes":"For final tempering","category":"Dairy"}]'::jsonb,
  '[{"step":1,"title":"Cook Rice & Dal Softly","instruction":"Pressure cook rice, toor dal, turmeric, and 5 cups water for 4-5 whistles until soft and porridge-like.","time":"15 mins","temp":"High pressure","visualCue":"Lentils and rice blend into a creamy soft base."},{"step":2,"title":"Simmer Vegetables & Tamarind","instruction":"In a pot, boil vegetables with 1 cup water, tamarind pulp, jaggery, salt, and bisi bele bath spice powder for 10 minutes until tender.","time":"10 mins","temp":"Medium heat","visualCue":"Vegetables soften and absorb aromatic spices."},{"step":3,"title":"Combine & Emulsify","instruction":"Stir cooked rice and dal into the spiced vegetables. Simmer gently for 5 minutes, adding warm water to maintain a luscious porridge consistency.","time":"5 mins","temp":"Low simmer","visualCue":"Rich amber-orange hot pot with silky texture."},{"step":4,"title":"Golden Ghee Cashew Tadka","instruction":"Heat ghee in a tadka pan. Fry mustard seeds, curry leaves, and cashews until golden brown. Pour sizzling over the dish.","time":"3 mins","temp":"Medium heat","visualCue":"Cashews turn nutty golden with popping mustard seeds."}]'::jsonb,
  '"A teaspoon of jaggery is non-negotiable; it balances the tart tamarind and fiery Byadagi chilies.","Serve hot with crunchy potato chips or boondi on top for incredible textural contrast."',
  '[{"original":"Ghee","alternative":"Coconut oil","notes":"Vegan alternative"}]'::jsonb,
  '[{"mistake":"Making the consistency too dry","remedy":"Bisi Bele Bath thickens as it cools; keep it slightly loose like risotto."}]'::jsonb,
