  '"High speed spice grinder","Heavy kadai or pan"',
  '[{"name":"Fresh Hilsa, Sea Bass, or Salmon steaks","amount":500,"unit":"g","notes":"Cleaned & salted","category":"Proteins"},{"name":"Yellow mustard seeds","amount":2,"unit":"tbsp","notes":"Mild sweetness","category":"Spices"},{"name":"Black mustard seeds","amount":1,"unit":"tbsp","notes":"Sharp pungency","category":"Spices"},{"name":"Green chilies","amount":6,"unit":"whole","notes":"Slit lengthwise","category":"Produce"},{"name":"Turmeric powder & salt","amount":1,"unit":"tsp","notes":"Vibrant yellow","category":"Spices"},{"name":"Cold-pressed pure mustard oil","amount":3,"unit":"tbsp","notes":"Crucial for authentic flavor","category":"Pantry"},{"name":"Nigella seeds (kalo jeere)","amount":0.5,"unit":"tsp","notes":"Tempering spice","category":"Spices"}]'::jsonb,
  '[{"step":1,"title":"Grind Mustard Paste with Green Chili","instruction":"Soak yellow and black mustard seeds in warm water for 15 mins. Grind into a silky paste with 1 green chili, pinch salt, and 4 tbsp water.","time":"5 mins","temp":"Off heat","visualCue":"Smooth golden mustard paste."},{"step":2,"title":"Temper Nigella Seeds","instruction":"Heat mustard oil until it smokes gently and cools slightly. Add nigella seeds and slit green chilies until they pop.","time":"2 mins","temp":"Medium heat","visualCue":"Pungent mustard aroma with crackling seeds."},{"step":3,"title":"Simmer Fish in Mustard Sauce","instruction":"Add turmeric, mustard paste, 1 cup warm water, and salt. Gently arrange fish steaks in the pan. Cover and simmer 10 minutes until fish is cooked through.","time":"10 mins","temp":"Medium-low heat","visualCue":"Fish absorbs the golden mustard gravy."},{"step":4,"title":"Raw Mustard Oil Finish","instruction":"Drizzle 1 tsp raw mustard oil on top and cover for 2 minutes before serving hot with steamed white rice.","time":"2 mins","temp":"Off heat","visualCue":"Sharp mustard hit and glossy yellow gravy."}]'::jsonb,
  '"Always grind mustard seeds with a pinch of salt and green chili to prevent the paste from turning bitter.","Mixing yellow and black mustard balances fierce heat with sweet seed flavor."',
