  '"Vegetarian","Festive","Signature","Traditional","Comfort Food","Rajasthani","Indian","Jain-Friendly","High-Protein"',
  '"Oven or Baati gas tandoor","Pressure cooker","Mixing bowls"',
  '[{"name":"Coarse whole wheat flour (atta)","amount":350,"unit":"g","notes":"For baati dough","category":"Pantry"},{"name":"Semolina (sooji)","amount":50,"unit":"g","notes":"For crisp texture","category":"Pantry"},{"name":"Pure desi ghee","amount":150,"unit":"g","notes":"For kneading, baking & dipping","category":"Dairy"},{"name":"Panchmel dal (mix of toor, moong, chana, urad, masoor)","amount":200,"unit":"g","notes":"Five-lentil mix","category":"Pantry"},{"name":"Powdered jaggery or sugar","amount":100,"unit":"g","notes":"For sweet churma","category":"Pantry"},{"name":"Green cardamom & roasted almonds","amount":1,"unit":"tbsp","notes":"For churma","category":"Spices"}]'::jsonb,
  '[{"step":1,"title":"Knead & Shape Baatis","instruction":"Mix wheat flour, semolina, ajwain seeds, salt, and 4 tbsp ghee. Knead into a very firm, tight dough with water. Roll into smooth balls with a small cross indent on top.","time":"15 mins","temp":"Room temp","visualCue":"Firm dough balls that hold their shape."},{"step":2,"title":"Bake Baatis","instruction":"Bake in preheated oven at 375°F (190°C) for 30 minutes, turning once until golden brown with cracked tops.","time":"30 mins","temp":"375°F (190°C)","visualCue":"Firm golden shell with rustic visible cracks."},{"step":3,"title":"Pressure Cook Panchmel Dal","instruction":"Cook 5 lentils with turmeric and salt for 4 whistles. Temper with ghee, cumin seeds, hing, chopped garlic, and Kashmiri chili.","time":"20 mins","temp":"Medium heat","visualCue":"Hearty, aromatic spiced lentil stew."},{"step":4,"title":"Ghee Dip & Churma","instruction":"Crush 2 baked baatis into fine crumbs, mix with melted ghee, powdered sugar, and cardamom for churma. Dip remaining hot baatis into melted ghee and serve with dal.","time":"10 mins","temp":"Warm","visualCue":"Glistening ghee-soaked baatis with sweet nutty churma."}]'::jsonb,
  '"The dough for baatis must be very firm, much tighter than roti dough, to achieve the authentic crumbly texture.","Press hot baatis gently with a towel to crack open before dipping in ghee so it absorbs completely."',
  '[{"original":"Panchmel dal","alternative":"Yellow toor dal or moong dal","notes":"Simplified version"}]'::jsonb,
  '[{"mistake":"Making dough too soft with excess water","remedy":"Soft dough makes bread buns instead of crisp rustic baatis."}]'::jsonb,
  '"Gluten","Dairy","Nuts"',
  'Use a clean kitchen towel when pressing hot baked baatis.',
  'Baked baatis keep at room temperature for 5 days.',
  'https://images.unsplash.com/photo-1601050690597-df0568f70950?auto=format&fit=crop&w=1000&q=80',
  false,
