  '"Heavy clay pot or Dutch oven","Charcoal briquette & small bowl for Dhungar"',
  '[{"name":"Bone-in goat or lamb pieces","amount":750,"unit":"g","notes":"Trimmed","category":"Proteins"},{"name":"Mathania dry red chilies (soaked in warm water)","amount":15,"unit":"whole","notes":"Authentic Rajasthani chili","category":"Spices"},{"name":"Mustard oil","amount":4,"unit":"tbsp","notes":"Pungent base","category":"Pantry"},{"name":"Garlic cloves, crushed","amount":15,"unit":"cloves","notes":"Generous garlic","category":"Produce"},{"name":"Plain yogurt","amount":0.5,"unit":"cup","notes":"Whisked with chili paste","category":"Dairy"},{"name":"Whole black cardamom, cloves & cinnamon","amount":1,"unit":"tbsp","notes":"Whole spices","category":"Spices"}]'::jsonb,
  '[{"step":1,"title":"Grind Mathania Chili Paste","instruction":"Grind soaked Mathania chilies with crushed garlic and 3 tbsp water into a smooth, fiery red paste. Whisk into plain yogurt.","time":"5 mins","temp":"Off heat","visualCue":"Brilliant glowing scarlet paste."},{"step":2,"title":"Brown Meat in Mustard Oil","instruction":"Heat mustard oil in heavy pot. Add whole spices and sliced onions. Brown meat on high heat for 10 minutes until deeply seared.","time":"12 mins","temp":"High heat","visualCue":"Meat develops caramelized crust."},{"step":3,"title":"Slow Braise in Chili Gravy","instruction":"Pour in spiced chili-yogurt paste. Simmer covered on low heat for 45 minutes until meat is fork-tender and crimson oil surfaces.","time":"45 mins","temp":"Low simmer","visualCue":"Glistening red oil layer floating on rich curry."},{"step":4,"title":"Live Charcoal Smoke (Dhungar)","instruction":"Place a small steel bowl on top of curry with red-hot charcoal. Pour 1 tsp ghee on charcoal and cover pot tightly for 3 minutes to trap smoke.","time":"3 mins","temp":"Covered tightly","visualCue":"Heady, rustic woodsmoke infused into the curry."}]'::jsonb,
  '"Mathania chilies provide intense red color and sweet smokiness without burning raw heat.","The dhungar charcoal smoke technique replicates outdoor campfire cooking from royal desert hunts."',
  '[{"original":"Mathania chilies","alternative":"Kashmiri dried chilies + 1 pinch cayenne","notes":"Matches color and heat"}]'::jsonb,
  '[{"mistake":"Leaving charcoal smoke for over 5 minutes","remedy":"Smoke will turn acrid; limit to 3 minutes max."}]'::jsonb,
  '"Dairy"',
  'Handle hot charcoal with metal tongs only.',
  'Refrigerate up to 4 days.',
  'https://images.unsplash.com/photo-1574484284002-952d92456975?auto=format&fit=crop&w=1000&q=80',
  false,
