  '[{"name":"Crispy puris (hollow semolina balls)","amount":30,"unit":"pieces","notes":"Crisp","category":"Pantry"},{"name":"Boiled potatoes & black chickpeas","amount":300,"unit":"g","notes":"Mashed with chaat masala","category":"Produce"},{"name":"Fresh mint & cilantro leaves","amount":2,"unit":"cups","notes":"For spicy green water","category":"Produce"},{"name":"Black salt (kala namak) & roasted cumin","amount":1.5,"unit":"tbsp","notes":"Signature aroma","category":"Spices"},{"name":"Sweet date-tamarind chutney","amount":0.5,"unit":"cup","notes":"Thick sweet dip","category":"Pantry"},{"name":"Chilled water with ice cubes","amount":4,"unit":"cups","notes":"Ice-cold spicy water","category":"Pantry"}]'::jsonb,
  '[{"step":1,"title":"Blend Tangy Mint Pani","instruction":"Blend fresh mint, cilantro, green chilies, ginger, and lemon juice with 0.5 cup water until smooth. Strain through sieve into chilled water.","time":"5 mins","temp":"Chilled","visualCue":"Brilliant vivid green herbal water."},{"step":2,"title":"Season Green Water","instruction":"Stir in black salt, roasted cumin powder, chaat masala, and ice cubes. Chill in refrigerator 30 mins to meld flavors.","time":"5 mins","temp":"Ice cold","visualCue":"Aromatically tangy, spiced refreshing broth."},{"step":3,"title":"Prepare Potato-Chickpea Filling","instruction":"Mash boiled potatoes with cooked black chickpeas, red chili powder, chaat masala, and salt.","time":"5 mins","temp":"Room temp","visualCue":"Moist spiced potato mash."},{"step":4,"title":"Assemble & Pop in Mouth","instruction":"Gently crack top of crisp puri with thumb. Add a spoonful of potato filling, a drizzle of sweet chutney, fill with ice-cold mint water, and eat in one bite!","time":"2 mins","temp":"Ice cold","visualCue":"Crisp shell bursting with cold spicy and sweet juices."}]'::jsonb,
  '"Black salt (kala namak) is the secret ingredient that gives the street cart flavor to the spicy water.","Serve the green water ice-cold; the contrast between hot spices and cold water is magical."',
