  '[{"step":1,"title":"Prick & Deep Fry Baby Potatoes","instruction":"Prick peeled baby potatoes thoroughly with a toothpick. Fry in hot mustard oil until deeply golden and blistered crisp. Drain.","time":"12 mins","temp":"360°F (180°C)","visualCue":"Golden brown crispy skin all over."},{"step":2,"title":"Whisk Spiced Yogurt Gravy","instruction":"Whisk plain yogurt with Kashmiri chili powder, fennel powder, dry ginger, and salt until smooth.","time":"3 mins","temp":"Room temp","visualCue":"Rich crimson yogurt emulsion."},{"step":3,"title":"Temper Spices in Mustard Oil","instruction":"Heat 2 tbsp mustard oil in pot. Add cloves, cardamoms, and pinch of hing. Lower heat and pour in spiced yogurt, whisking continuously to prevent curdling.","time":"5 mins","temp":"Low heat","visualCue":"Smooth bubbling red yogurt sauce."},{"step":4,"title":"Dum Simmer Potatoes","instruction":"Add fried potatoes. Cover tightly and simmer on low for 15 minutes until potatoes absorb the yogurt gravy.","time":"15 mins","temp":"Lowest simmer","visualCue":"Sauce clings richly to wrinkled, flavor-soaked potatoes."}]'::jsonb,
  '"Pricking the potatoes before frying allows the spiced fennel yogurt to penetrate all the way to the potato's core.","Whisk yogurt continuously over low heat until it comes to a gentle simmer to prevent it from splitting."',
