  '[{"name":"Crispy potato samosas (hot)","amount":4,"unit":"pieces","notes":"Fresh or freshly reheated","category":"Pantry"},{"name":"Warm spiced chickpea curry (chole)","amount":2,"unit":"cups","notes":"Savory stew","category":"Pantry"},{"name":"Whisked sweet yogurt (dahi)","amount":1,"unit":"cup","notes":"Cold, lightly sweetened","category":"Dairy"},{"name":"Spicy mint-cilantro chutney","amount":4,"unit":"tbsp","notes":"Zesty green","category":"Produce"},{"name":"Sweet tamarind date chutney","amount":4,"unit":"tbsp","notes":"Tangy sweet brown","category":"Pantry"},{"name":"Crispy nylon sev & pomegranate seeds","amount":0.5,"unit":"cup","notes":"Crunch & fresh pop","category":"Pantry"},{"name":"Chaat masala & roasted cumin powder","amount":1,"unit":"tsp","notes":"Finishing dust","category":"Spices"}]'::jsonb,
  '[{"step":1,"title":"Crush Hot Samosas","instruction":"Place 1 hot crispy samosa in each shallow serving bowl. Gently crush open with a spoon so the spiced potato filling is exposed.","time":"1 min","temp":"Hot","visualCue":"Flaky crust cracked open with fragrant potato filling visible."},{"step":2,"title":"Ladle Warm Chole","instruction":"Ladle warm spiced chickpea curry generously over and around the crushed samosas.","time":"2 mins","temp":"Hot","visualCue":"Rich brown chickpeas pooling around crispy pastry."},{"step":3,"title":"Layer Cold Yogurt & Chutneys","instruction":"Drizzle sweet whipped yogurt across the dish, followed by ribbons of green mint chutney and sweet dark tamarind chutney.","time":"2 mins","temp":"Contrast hot & cold","visualCue":"Artistic swirls of white, green, and dark amber."},{"step":4,"title":"Garnish for Crunch & Pop","instruction":"Top with crunchy nylon sev, chopped onions, ruby pomegranate arils, and a sprinkle of chaat masala. Serve immediately.","time":"1 min","temp":"Serve immediately","visualCue":"Sensational rainbow street food bowl."}]'::jsonb,
  '"The magic of chaat comes from the temperature contrast: piping hot samosa and chole paired with ice-cold sweet yogurt.","Serve immediately after assembling so the pastry maintains its crisp flakiness."',
