  '[{"name":"Raw rice (soaked 4 hours)","amount":300,"unit":"g","notes":"Ground with coconut","category":"Pantry"},{"name":"Grated fresh coconut","amount":1,"unit":"cup","notes":"For batter & stew","category":"Produce"},{"name":"Instant yeast or coconut toddy","amount":0.5,"unit":"tsp","notes":"For overnight fermentation","category":"Pantry"},{"name":"Thick & thin coconut milk","amount":2,"unit":"cups","notes":"For vegetable stew","category":"Pantry"},{"name":"Carrots, potatoes & green beans, diced","amount":300,"unit":"g","notes":"Stew vegetables","category":"Produce"},{"name":"Whole cinnamon, cardamom & cloves","amount":1,"unit":"tbsp","notes":"Gentle stew spices","category":"Spices"},{"name":"Fresh curry leaves & coconut oil","amount":2,"unit":"tbsp","notes":"Aromatics","category":"Produce"}]'::jsonb,
  '[{"step":1,"title":"Ferment Appam Batter","instruction":"Grind soaked rice and coconut with cooked rice into a smooth batter. Stir in yeast, pinch sugar, and salt. Ferment overnight (8 hours) until frothy and doubled.","time":"10 mins + ferment","temp":"Warm spot","visualCue":"Airy, bubbling sweet-scented batter."},{"step":2,"title":"Simmer Gentle Coconut Stew","instruction":"Simmer diced vegetables in thin coconut milk with ginger, green chilies, and whole spices for 12 mins. Stir in thick coconut milk and remove from heat before boiling.","time":"15 mins","temp":"Low heat","visualCue":"Pristine white, fragrant coconut vegetable stew."},{"step":3,"title":"Swirl the Appam","instruction":"Heat appa chatti, pour a ladle of batter into center, hold both handles, and swirl quickly in a circular motion so batter coats sides and pools in center.","time":"1 min","temp":"Medium heat","visualCue":"Thin batter clings to sides with pooled center."},{"step":4,"title":"Steam Under Lid","instruction":"Cover with lid and cook 2 minutes without flipping. Edges will turn crisp and brown while center remains a pillowy white cloud.","time":"2 mins","temp":"Medium heat","visualCue":"Lacy golden crispy rim and soft spongy center."}]'::jsonb,
  '"Swirl the pan only once in a swift, confident motion to ensure even, delicate lace edges.","Never flip an appam; it cooks entirely by trapped steam under the curved lid."',
  '[{"original":"Vegetable stew","alternative":"Chicken or mutton coconut stew","notes":"Classic non-veg pairing"}]'::jsonb,
  '[{"mistake":"Using cold batter","remedy":"Always let batter sit at room temperature before swirling."}]'::jsonb,
  '{}',
  'Pan handles get hot; use dry cloth.',
  'Eat appams fresh off the pan; stew keeps 3 days in fridge.',
