  '[{"name":"Surti papdi & valor beans (stringed)","amount":300,"unit":"g","notes":"Tender flat beans","category":"Produce"},{"name":"Purple yam (kand) & baby potatoes","amount":300,"unit":"g","notes":"Diced & deep-fried","category":"Produce"},{"name":"Baby eggplants (brinjal), slit in cross","amount":6,"unit":"whole","notes":"Stuffed with masala","category":"Produce"},{"name":"Fresh methi (fenugreek) muthiya dumplings","amount":12,"unit":"pieces","notes":"Fried golden","category":"Pantry"},{"name":"Fresh grated coconut, cilantro & green garlic","amount":1.5,"unit":"cups","notes":"Aromatic stuffing masala","category":"Produce"},{"name":"Sesame seeds, carom seeds (ajwain) & ground spices","amount":2,"unit":"tbsp","notes":"Masala seasoning","category":"Spices"},{"name":"Peanut oil","amount":4,"unit":"tbsp","notes":"Authentic Gujarati medium","category":"Pantry"}]'::jsonb,
  '[{"step":1,"title":"Prepare Coconut-Green Garlic Masala","instruction":"Mix grated coconut, green garlic, fresh cilantro, sesame seeds, ginger, green chilies, sugar, and spices into a damp stuffing paste.","time":"8 mins","temp":"Room temp","visualCue":"Vibrant green aromatic coconut mixture."},{"step":2,"title":"Fry Muthiya & Tubers","instruction":"Fry methi muthiya balls until golden and crisp. Flash-fry purple yam and potatoes for 5 mins to seal edges.","time":"10 mins","temp":"350°F (175°C)","visualCue":"Golden brown dumplings and sealed tubers."},{"step":3,"title":"Stuff Eggplants & Layer Pot","instruction":"Stuff baby eggplants with green masala. In pot, layer beans at bottom, followed by stuffed eggplants, fried tubers, remaining masala, and muthiya on top.","time":"10 mins","temp":"Room temp","visualCue":"Colorful layered harvest vegetables in pot."},{"step":4,"title":"Slow Dum Braise","instruction":"Add 0.5 cup water and peanut oil. Cover tightly and simmer on low for 30 minutes until vegetables are tender and fragrant. Gently toss and serve with hot puris.","time":"30 mins","temp":"Low simmer","visualCue":"Rich, glistening aromatic green vegetable medley."}]'::jsonb,
  '"Fresh winter green garlic (hara lasun) is what gives authentic Surti undhiyu its unmistakable fragrance.","Layer the beans at the bottom and delicate muthiya dumplings at the top so they don't crush."',
  '[{"original":"Surti papdi","alternative":"Italian flat beans or snow peas","notes":"Seasonal swap"}]'::jsonb,
  '[{"mistake":"Stirring vigorously with a ladle","remedy":"Toss gently by shaking the pot so tender eggplants and muthiya stay whole."}]'::jsonb,
