  '[{"name":"Mixed vegetables (raw banana, yam, drumstick, carrot, beans)","amount":500,"unit":"g","notes":"Cut into 2-inch batons","category":"Produce"},{"name":"Fresh grated coconut","amount":1.5,"unit":"cups","notes":"Coarsely crushed","category":"Produce"},{"name":"Cumin seeds (jeera) & green chilies","amount":1,"unit":"tbsp","notes":"Crushed with coconut","category":"Spices"},{"name":"Sour plain yogurt (curd)","amount":0.3,"unit":"cup","notes":"Whisked","category":"Dairy"},{"name":"Virgin cold-pressed coconut oil","amount":2,"unit":"tbsp","notes":"Raw finish","category":"Pantry"},{"name":"Fresh curry leaves","amount":2,"unit":"sprigs","notes":"Aromatics","category":"Produce"}]'::jsonb,
  '[{"step":1,"title":"Steam Vegetables","instruction":"Cook vegetables with 0.5 cup water, turmeric, and salt in a pot covered for 10 minutes until tender but firm (al dente).","time":"10 mins","temp":"Medium heat","visualCue":"Vegetables soften without turning to mush."},{"step":2,"title":"Coarsely Crush Coconut & Cumin","instruction":"Pulse grated coconut, cumin seeds, and green chilies in a grinder for 3 seconds into a coarse crumbly mixture without adding water.","time":"2 mins","temp":"Room temp","visualCue":"Rough, fragrant green-flecked coconut crumble."},{"step":3,"title":"Fold Coconut into Vegetables","instruction":"Add crushed coconut to the vegetables. Cover and steam for 3 minutes until raw coconut aroma mellows.","time":"3 mins","temp":"Low heat","visualCue":"Coconut warms and coats vegetable batons."},{"step":4,"title":"Raw Coconut Oil & Curry Leaf Finish","instruction":"Stir in whisked yogurt. Turn off heat immediately. Drizzle raw virgin coconut oil and fresh curry leaves over top, cover, and rest 5 mins.","time":"2 mins","temp":"Off heat","visualCue":"Glossy, thick pale-yellow vegetable medley with raw coconut aroma."}]'::jsonb,
