  '[{"step":1,"title":"Sun-Dry & Fry Bread Triangles","instruction":"Air-dry sliced bread triangles on counter for 2 hours (drier bread absorbs less fat). Deep fry in hot ghee until deeply golden and crisp. Drain.","time":"8 mins","temp":"360°F (180°C)","visualCue":"Dark golden brown, shatteringly crisp bread croutons."},{"step":2,"title":"Simmer Saffron Sugar Syrup","instruction":"Boil sugar and 1 cup water with crushed cardamom and saffron for 6 minutes until a single-thread syrup forms.","time":"6 mins","temp":"Medium heat","visualCue":"Golden-amber aromatic syrup."},{"step":3,"title":"Reduce Silken Rabri","instruction":"Simmer whole milk with 2 tbsp sugar and saffron on low heat, stirring occasionally, until reduced by half into rich, creamy rabri.","time":"20 mins","temp":"Low simmer","visualCue":"Thick, creamy pale gold condensed milk."},{"step":4,"title":"Layer & Soak","instruction":"Dip fried bread into warm saffron syrup, arrange in a single layer in serving dish, and pour warm rabri generously over top. Garnish with toasted nuts and silver leaf.","time":"5 mins","temp":"Warm","visualCue":"Crisp bread slowly softening in decadent golden saffron cream."}]'::jsonb,
  '"Air-drying the bread slices for a few hours before frying makes them absorb significantly less ghee and stay firmer in the milk.","Pour the rabri while warm so the bread drinks it up like a sponge."',
