  '[{"step":1,"title":"Flash Sear Prawns","instruction":"Rub prawns with turmeric and salt. Flash-fry in hot mustard oil for exactly 60 seconds per side until pink. Remove immediately to prevent toughening.","time":"3 mins","temp":"High heat","visualCue":"Prawns curl slightly into bright orange-pink."},{"step":2,"title":"Sauté Onion Paste & Aromatics","instruction":"In same oil, fry whole spices, onion paste, and ginger-garlic paste until fragrant and golden.","time":"8 mins","temp":"Medium heat","visualCue":"Aromatics caramelize into sweet golden base."},{"step":3,"title":"Simmer in Coconut Cream","instruction":"Pour in coconut milk, slit green chilies, pinch sugar, and salt. Simmer 5 mins until sauce thickens into a silken golden gravy.","time":"5 mins","temp":"Medium-low heat","visualCue":"Bubbling, creamy ivory-gold sauce."},{"step":4,"title":"Poach Prawns in Sauce","instruction":"Return seared prawns to sauce. Simmer gently for 3 minutes, finish with 1 tsp ghee, and serve hot with fragrant basmati rice.","time":"3 mins","temp":"Low heat","visualCue":"Succulent prawns nestled in velvety coconut sauce."}]'::jsonb,
