  '[{"step":1,"title":"Knead Methi Dough","instruction":"Combine wheat flour, chopped methi leaves, yogurt, sesame seeds, ajwain, turmeric, chili powder, and salt. Knead into a soft, smooth dough with minimal water.","time":"8 mins","temp":"Room temp","visualCue":"Green-speckled, soft pliable dough."},{"step":2,"title":"Roll Paper-Thin","instruction":"Divide into golf-ball sized rounds. Dust with dry flour and roll out as thin as a tortilla.","time":"5 mins","temp":"Room temp","visualCue":"Thin, translucent speckled round flatbread."},{"step":3,"title":"Roast on Tawa","instruction":"Cook on medium-high tawa for 30 seconds per side. Drizzle 0.5 tsp oil, press gently with spatula, and roast until golden-brown spots appear.","time":"4 mins","temp":"Medium-high heat","visualCue":"Soft, flexible flatbread speckled with golden freckles."}]'::jsonb,
