  '[{"name":"Chana dal (Bengal gram), boiled soft","amount":250,"unit":"g","notes":"Drained well","category":"Pantry"},{"name":"Jaggery (gur), finely chopped","amount":250,"unit":"g","notes":"Dark sticky jaggery","category":"Pantry"},{"name":"Green cardamom powder & ground nutmeg","amount":1,"unit":"tbsp","notes":"Sweet warming spice","category":"Spices"},{"name":"Whole wheat flour & all-purpose flour blend","amount":300,"unit":"g","notes":"Super soft outer dough","category":"Pantry"},{"name":"Desi ghee","amount":4,"unit":"tbsp","notes":"For roasting & serving","category":"Dairy"}]'::jsonb,
  '[{"step":1,"title":"Cook Sweet Puran Filling","instruction":"Cook boiled chana dal and chopped jaggery in a pan over medium heat for 15 mins until mixture thickens and a wooden spatula stands upright. Stir in cardamom and nutmeg. Pass through puran sieve until silky.","time":"15 mins","temp":"Medium heat","visualCue":"Dense, smooth golden-amber sweet paste."},{"step":2,"title":"Knead Silky Dough","instruction":"Knead flour with pinch turmeric, water, and 2 tbsp oil into an ultra-soft, elastic dough. Rest 30 mins.","time":"5 mins + rest","temp":"Room temp","visualCue":"Stretchy, pliable dough that mimics soft clay."},{"step":3,"title":"Stuff & Roll Thin","instruction":"Take equal portions of dough and sweet puran ball. Encase puran inside dough and seal seams. Roll out gently with light pressure into a thin disc.","time":"5 mins","temp":"Room temp","visualCue":"Thin golden flatbread with filling visible beneath translucent skin."},{"step":4,"title":"Roast with Ghee","instruction":"Roast on hot tawa, basting with pure ghee until it puffs up like a balloon with golden freckles. Serve warm with warm milk or katachi amti.","time":"3 mins","temp":"Medium-high heat","visualCue":"Puffed, golden-glistening flatbread with sweet spiced aroma."}]'::jsonb,
  '"Passing the warm puran through a fine puran yantra or sieve produces an ultra-smooth silk filling that rolls without tearing the dough.","Serve hot with a pool of warm molten ghee on top."',
