  '"Roasting pan with wire rack","Basting brush","Meat thermometer"',
  '[{"name":"Pork tenderloin or pork shoulder strips","amount":750,"unit":"g","notes":"Cut into 2-inch wide strips","category":"Proteins"},{"name":"Red fermented bean curd (nanru)","amount":2,"unit":"cubes","notes":"Provides signature red hue","category":"Pantry"},{"name":"Chinese five-spice powder","amount":1,"unit":"tsp","notes":"Fragrant","category":"Spices"},{"name":"Hoisin sauce & soy sauce","amount":3,"unit":"tbsp","notes":"Savory base","category":"Pantry"},{"name":"Shaoxing rice wine","amount":2,"unit":"tbsp","notes":"Aromatic","category":"Pantry"},{"name":"Maltose or raw honey","amount":3,"unit":"tbsp","notes":"For sticky glossy glaze","category":"Pantry"},{"name":"Garlic, finely minced","amount":4,"unit":"cloves","notes":"Fresh","category":"Produce"}]'::jsonb,
  '[{"step":1,"title":"Marinate Pork Strips","instruction":"Whisk mashed fermented red bean curd, five-spice, hoisin, soy sauce, Shaoxing wine, minced garlic, and sugar. Coat pork thoroughly and marinate refrigerated for at least 6 hours.","time":"10 mins + chill","temp":"Refrigerated","visualCue":"Pork is saturated in vibrant dark crimson marinade."},{"step":2,"title":"Roast on Wire Rack","instruction":"Preheat oven to 400°F (200°C). Place marinated pork on wire rack over water-filled tray. Roast 20 minutes.","time":"20 mins","temp":"400°F (200°C)","visualCue":"Meat firming up with edges starting to caramelize."},{"step":3,"title":"Baste with Honey Maltose Glaze","instruction":"Warm maltose/honey with 1 tbsp reserved marinade. Brush generously over all sides of pork. Roast 10 more minutes.","time":"10 mins","temp":"400°F (200°C)","visualCue":"Lustrous lacquer finish with sticky amber bubbles."},{"step":4,"title":"Broil for Charred Tips","instruction":"Broil on high for 3-4 minutes until corners develop blackened crispy barbecue tips. Rest 10 mins before slicing thinly.","time":"4 mins","temp":"Broil High","visualCue":"Glossy crimson crust with smoky charred edges and tender pink interior."}]'::jsonb,
  '"Maltose gives that authentic glass-like sheen that honey alone cannot achieve.","Placing a water bath in the pan below catches drips and prevents smoking."',
