  '[{"name":"Soft or medium silken tofu, cut in 1-inch cubes","amount":450,"unit":"g","notes":"Handled gently","category":"Proteins"},{"name":"Ground beef or pork","amount":120,"unit":"g","notes":"Minced fine","category":"Proteins"},{"name":"Pixian fermented chili bean paste (doubanjiang)","amount":2,"unit":"tbsp","notes":"Finely minced","category":"Pantry"},{"name":"Fermented black beans (douchi)","amount":1,"unit":"tbsp","notes":"Coarsely chopped","category":"Pantry"},{"name":"Sichuan peppercorn powder","amount":1.5,"unit":"tsp","notes":"Freshly roasted & ground","category":"Spices"},{"name":"Chili oil & scallions","amount":2,"unit":"tbsp","notes":"For garnish","category":"Pantry"},{"name":"Cornstarch slurry","amount":2,"unit":"tbsp","notes":"Divided in 3 additions","category":"Pantry"}]'::jsonb,
  '[{"step":1,"title":"Salt-Water Poach Tofu","instruction":"Gently submerge tofu cubes in hot salted water for 3 minutes to firm up structure and prevent breaking in the wok. Drain gently.","time":"4 mins","temp":"Gentle simmer","visualCue":"Tofu cubes become plump and resilient."},{"step":2,"title":"Crisp the Minced Beef","instruction":"Brown minced beef in 1 tbsp oil on medium-high until crispy and deep brown. Add Pixian doubanjiang and douchi. Fry until oil turns glowing red.","time":"4 mins","temp":"Medium heat","visualCue":"Vibrant ruby-red oil with fragrant chili aroma."},{"step":3,"title":"Simmer Tofu Gently","instruction":"Add garlic, ginger, and 1 cup stock. Slide in poached tofu. Simmer gently for 4 minutes to let tofu absorb the sauce.","time":"4 mins","temp":"Low simmer","visualCue":"Tofu cubes nestled in bubbling crimson gravy."},{"step":4,"title":"Three-Stage Starch Thicken & Dust Pepper","instruction":"Drizzle cornstarch slurry in 3 batches, swirling gently with back of spatula. Once sauce is glossy, plate and dust heavily with roasted Sichuan peppercorn powder.","time":"3 mins","temp":"Low heat","visualCue":"Glossy red sauce clinging to tender white tofu with numbing pepper cloud."}]'::jsonb,
  '"Poaching tofu in hot salted water draws out excess water and firms the protein structure so cubes don't crumble.","Add the cornstarch slurry in three distinct additions to achieve a glassy sauce that doesn't split."',
