  '[{"step":1,"title":"Heat Broth & Prepare Tare","instruction":"Simmer rich broth until piping hot. In each serving bowl, add 1 tbsp shoyu tare and 1 tsp aroma oil.","time":"10 mins","temp":"Rolling simmer","visualCue":"Steaming broth with glossy oil surface."},{"step":2,"title":"Boil Fresh Noodles","instruction":"Cook fresh ramen noodles in rolling boiling water for precisely 90 seconds. Vigorously shake out all excess water in noodle strainer.","time":"2 mins","temp":"Boiling","visualCue":"Springy, al dente noodles with firm bite."},{"step":3,"title":"Pour Broth & Fold Noodles","instruction":"Ladle 1.5 cups hot broth into bowls and whisk with tare. Fold in drained noodles with chopsticks to create a neat bundle.","time":"1 min","temp":"Piping hot","visualCue":"Velvety broth coating bouncy noodle strands."},{"step":4,"title":"Arrange Toppings","instruction":"Top with seared chashu slices, halved jammy marinated egg, menma bamboo shoots, scallions, and a crisp square of nori.","time":"2 mins","temp":"Serve immediately","visualCue":"Stunning Japanese ramen shop presentation."}]'::jsonb,
