  '[{"name":"Chicken breasts or thighs, pounded to 1/2-inch","amount":4,"unit":"cutlets","notes":"Uniform thickness","category":"Proteins"},{"name":"Japanese panko breadcrumbs","amount":2,"unit":"cups","notes":"Extra crispy flakes","category":"Pantry"},{"name":"Japanese curry roux blocks (S&B or Golden Curry)","amount":100,"unit":"g","notes":"Medium hot","category":"Pantry"},{"name":"Grated Fuji apple & honey","amount":2,"unit":"tbsp","notes":"Sweet diner secret","category":"Produce"},{"name":"Onion, carrots & Yukon gold potatoes","amount":350,"unit":"g","notes":"Chunky cuts","category":"Produce"},{"name":"Steamed Japanese short-grain rice","amount":4,"unit":"cups","notes":"Warm","category":"Pantry"},{"name":"Fukujinzuke (red pickled daikon)","amount":4,"unit":"tbsp","notes":"Garnish","category":"Pantry"}]'::jsonb,
  '[{"step":1,"title":"Simmer Japanese Curry","instruction":"Sauté sliced onions, carrots, and potatoes in oil for 5 mins. Add 3 cups water, bring to boil, and simmer 15 mins. Turn off heat, dissolve curry blocks, stir in grated apple, and simmer 5 mins until thick.","time":"20 mins","temp":"Medium heat","visualCue":"Glossy, thick aromatic brown curry."},{"step":2,"title":"Standard Breading Procedure","instruction":"Dredge seasoned chicken in flour, dip in beaten egg, and press firmly into panko crumbs until completely encrusted.","time":"8 mins","temp":"Room temp","visualCue":"Thick, even coat of airy breadcrumb shards."},{"step":3,"title":"Golden Deep Fry","instruction":"Fry cutlets in 350°F (175°C) oil for 5-6 minutes, flipping once until golden amber. Rest on wire rack 3 minutes, then slice into 1-inch strips.","time":"8 mins","temp":"350°F (175°C)","visualCue":"Shatteringly crisp golden crust with juicy white meat."},{"step":4,"title":"Plate Half-Rice Half-Curry","instruction":"Mound warm rice on half of plate. Arrange sliced katsu over rice. Ladle rich curry around and garnish with red pickles.","time":"2 mins","temp":"Hot","visualCue":"Golden katsu resting against velvety brown curry."}]'::jsonb,
  '"Grated apple and a touch of honey give that irresistible savory-sweet umami depth characteristic of Japanese family diners.","Resting the fried katsu on a wire rack instead of paper towels keeps the bottom crust crisp."',
