  '[{"name":"Fresh Atlantic or King salmon fillets","amount":4,"unit":"fillets","notes":"Skin on, 180g each","category":"Proteins"},{"name":"Saikyo white miso paste (sweet white miso)","amount":0.5,"unit":"cup","notes":"Milder & sweeter than red","category":"Pantry"},{"name":"Mirin (sweet cooking rice wine)","amount":3,"unit":"tbsp","notes":"Glaze sweetness","category":"Pantry"},{"name":"Japanese sake","amount":3,"unit":"tbsp","notes":"Tenderizer","category":"Pantry"},{"name":"Cane sugar","amount":2,"unit":"tbsp","notes":"For glossy caramelization","category":"Pantry"},{"name":"Hajikami (pickled ginger sprouts) or lemon wedges","amount":4,"unit":"pieces","notes":"Palate cleanser","category":"Produce"}]'::jsonb,
  '[{"step":1,"title":"Whisk Saikyo Miso Marinade","instruction":"Simmer sake and mirin in a small saucepan for 60 seconds to cook off alcohol. Whisk in sweet white miso and sugar until silky. Cool completely.","time":"5 mins","temp":"Medium heat","visualCue":"Smooth, golden-beige glossy glaze."},{"step":2,"title":"Cure Salmon","instruction":"Coat salmon fillets thoroughly in miso marinade. Wrap tightly in plastic wrap and refrigerate for 12 to 24 hours.","time":"5 mins + chill","temp":"Refrigerated","visualCue":"Salmon absorbs sweet umami essence and firms slightly."},{"step":3,"title":"Wipe Excess & Broil","instruction":"Gently wipe excess miso from surface (miso burns easily). Place skin-side down on foil-lined tray. Broil 6-8 inches from element for 8-10 minutes.","time":"10 mins","temp":"Broil High","visualCue":"Miso blisters into deep mahogany charred caramel bubbles with flaky tender center."}]'::jsonb,
  '"Always wipe off the thick layer of marinade before broiling; miso contains sugars that burn rapidly.","Saikyo white miso has a higher rice-to-soybean ratio, providing natural sweetness."',
