  '[{"name":"Steamed Korean short-grain rice","amount":4,"unit":"cups","notes":"Freshly cooked & warm","category":"Pantry"},{"name":"Thinly sliced ribeye or ground beef","amount":250,"unit":"g","notes":"Marinated in soy & sesame","category":"Proteins"},{"name":"Korean spinach namul (blanched & sesame dressed)","amount":1,"unit":"cup","notes":"Seasoned","category":"Produce"},{"name":"Soybean sprouts (Kongnamul)","amount":1,"unit":"cup","notes":"Boiled & sesame tossed","category":"Produce"},{"name":"Julienned carrots & shiitake mushrooms","amount":1.5,"unit":"cups","notes":"Sautéed separately","category":"Produce"},{"name":"Toasted sesame oil","amount":3,"unit":"tbsp","notes":"For stone bowl crisping","category":"Pantry"},{"name":"Korean gochujang bibimbap sauce","amount":4,"unit":"tbsp","notes":"Gochujang, honey, vinegar, sesame","category":"Pantry"},{"name":"Eggs","amount":4,"unit":"whole","notes":"Sunny-side up","category":"Dairy"}]'::jsonb,
  '[{"step":1,"title":"Sauté Vegetables & Beef Individually","instruction":"Sauté carrots, shiitake, and marinated beef in separate pans with drops of sesame oil and garlic. Keep each topping distinct.","time":"10 mins","temp":"Medium heat","visualCue":"Vibrant individual vegetable colors preserved."},{"step":2,"title":"Heat & Oil Stone Bowl","instruction":"Coat interior of Dolsot stone bowl (or cast-iron pan) generously with toasted sesame oil. Place over medium heat until sizzling hot.","time":"5 mins","temp":"Medium heat","visualCue":"Sesame oil glistens and begins sizzling."},{"step":3,"title":"Pack Rice & Arrange Toppings","instruction":"Press warm rice firmly against bottom and sides of stone bowl. Arrange colorful namul, sautéed vegetables, and beef in radial sections over rice. Place sunny-side-up egg in center.","time":"3 mins","temp":"Medium-low heat","visualCue":"Loud crackling sound as rice crust begins scorching."},{"step":4,"title":"Listen for the Crackle (Nurungji)","instruction":"Let sizzle on heat for 5 minutes without stirring until a golden-brown crispy crust forms underneath. Serve piping hot with gochujang sauce.","time":"5 mins","temp":"Medium-low heat","visualCue":"Audible crackle and irresistible toasted sesame rice aroma."}]'::jsonb,
  '"Don't rush to stir! Let the stone pot sit undisturbed for 5 minutes so the bottom rice layer turns into shatteringly crisp nurungji.","Stir with a long metal spoon right at the table to mix the runny yolk and spicy gochujang."',
  '[{"original":"Beef","alternative":"Pan-fried tofu or king oyster mushrooms","notes":"Vegetarian Bibimbap"}]'::jsonb,
