  '[{"name":"Dry rice stick noodles (soaked in warm water 30 mins)","amount":250,"unit":"g","notes":"Pliable, not soft","category":"Pantry"},{"name":"Plump tiger prawns, peeled & deveined","amount":300,"unit":"g","notes":"Tails intact","category":"Proteins"},{"name":"Extra firm yellow tofu, cut in batons","amount":150,"unit":"g","notes":"Pressed dry","category":"Proteins"},{"name":"Tamarind paste concentrate","amount":3,"unit":"tbsp","notes":"Sour backbone","category":"Pantry"},{"name":"Palm sugar or brown sugar","amount":3,"unit":"tbsp","notes":"Caramelized sweetness","category":"Pantry"},{"name":"Fish sauce (nam pla)","amount":2.5,"unit":"tbsp","notes":"Savory umami","category":"Pantry"},{"name":"Eggs","amount":2,"unit":"large","notes":"Scrambled in wok","category":"Dairy"},{"name":"Fresh bean sprouts & garlic chives","amount":2,"unit":"cups","notes":"Crunch","category":"Produce"},{"name":"Roasted crushed peanuts & lime wedges","amount":0.5,"unit":"cup","notes":"Garnish","category":"Pantry"}]'::jsonb,
  '[{"step":1,"title":"Whisk 3-Ingredient Pad Thai Sauce","instruction":"Warm tamarind paste, palm sugar, and fish sauce in a small saucepan until sugar dissolves completely. Balance should be equal parts sweet, sour, and savory.","time":"4 mins","temp":"Low heat","visualCue":"Glossy, amber-brown balanced syrup."},{"step":2,"title":"Sear Tofu & Prawns","instruction":"Heat 2 tbsp oil in smoking hot wok. Sauté tofu batons until golden crisp. Add prawns and cook 2 minutes until pink. Push to side of wok.","time":"3 mins","temp":"High heat","visualCue":"Prawns curl into plump pink crescents."},{"step":3,"title":"Wok-Toss Noodles & Sauce","instruction":"Add soaked drained noodles and half the tamarind sauce. Stir-fry briskly with splash of water until noodles absorb sauce and turn supple and chewy.","time":"3 mins","temp":"High heat","visualCue":"Noodles turn glistening amber-orange."},{"step":4,"title":"Scramble Egg & Finish Crunch","instruction":"Push noodles aside. Crack eggs into wok, scramble softly, and fold through noodles with bean sprouts and garlic chives. Serve with crushed peanuts and fresh lime.","time":"2 mins","temp":"High heat","visualCue":"Golden egg ribbons and crunchy sprouts dispersed through noodles."}]'::jsonb,
  '"Soak noodles in warm (not boiling) water for 30 minutes until pliable; boiling them beforehand makes them mushy in the wok.","Real Pad Thai sauce never uses ketchup; authentic orange hue comes from tamarind, palm sugar, and prawn oil."',
