  '"Large 8-quart stockpot","Fine mesh skimmer","Slotted spoon"',
  '[{"name":"Beef marrow bones & brisket","amount":1.5,"unit":"kg","notes":"Parboiled & washed clean","category":"Proteins"},{"name":"Thinly sliced eye of round beef (raw)","amount":300,"unit":"g","notes":"Paper-thin for bowl topping","category":"Proteins"},{"name":"Flat Pho rice noodles (banh pho)","amount":500,"unit":"g","notes":"Cooked soft","category":"Pantry"},{"name":"Yellow onions & fresh ginger","amount":2,"unit":"whole","notes":"Charred over open flame","category":"Produce"},{"name":"Star anise, cinnamon stick, black cardamom & cloves","amount":1,"unit":"spice sachet","notes":"Toasted aromatics","category":"Spices"},{"name":"Fish sauce (Nuoc Mam) & rock sugar","amount":4,"unit":"tbsp","notes":"Broth seasoning","category":"Pantry"},{"name":"Thai basil, cilantro, culantro, lime & bird''s eye chilies","amount":1,"unit":"platter","notes":"Fresh herb platter","category":"Produce"}]'::jsonb,
  '[{"step":1,"title":"Blanch Bones for Crystal-Clear Broth","instruction":"Cover beef bones with water, boil vigorously for 10 minutes to purge impurities. Drain and scrub bones thoroughly under cold water.","time":"15 mins","temp":"Rolling boil","visualCue":"Water turns scummy; washed bones are clean and white."},{"step":2,"title":"Char Aromatics over Flame","instruction":"Char unpeeled onions and ginger directly over open gas flame (or under broiler) until skins are blackened and fragrant. Peel off loose burnt skin.","time":"10 mins","temp":"Open flame","visualCue":"Blackened skins with sweet, smoky aroma."},{"step":3,"title":"Slow Simmer Golden Broth","instruction":"Simmer cleaned bones, brisket, charred aromatics, toasted spice sachet, rock sugar, and salt in 16 cups water on lowest heat for 90 mins (or up to 6 hours), skimming surface fat.","time":"90 mins","temp":"Bare simmer","visualCue":"Aromatic, golden-amber broth with tiny shimmering oil beads."},{"step":4,"title":"Assemble & Flash-Poach Beef","instruction":"Place warm noodles in deep bowls. Top with sliced brisket and raw beef slices. Ladle boiling broth directly over raw beef to poach it instantly to pink tenderness. Serve with fresh herb platter.","time":"3 mins","temp":"Boiling broth","visualCue":"Delicate pink beef turning tender grey in fragrant steaming broth."}]'::jsonb,
  '"Parboiling the bones and washing them thoroughly is the cardinal rule for achieving crystal-clear broth.","Pour the broth while boiling hot; this cooks the paper-thin raw beef directly in the bowl."',
  '[{"original":"Beef brisket","alternative":"Chicken carcass & poached breast","notes":"Classic Pho Ga (Chicken Pho)"}]'::jsonb,
  '[{"mistake":"Boiling broth vigorously instead of bare simmer","remedy":"Vigorous boiling emulsifies bone fat, making broth cloudy instead of crystal clear."}]'::jsonb,
