  '[{"name":"Fresh Chinese thin wheat noodles","amount":400,"unit":"g","notes":"Springy texture","category":"Pantry"},{"name":"Ground pork","amount":200,"unit":"g","notes":"Crisped in wok","category":"Proteins"},{"name":"Sui Mi Ya Cai (Sichuan pickled greens)","amount":3,"unit":"tbsp","notes":"Traditional savory crunch","category":"Pantry"},{"name":"Chinese toasted sesame paste (or tahini)","amount":3,"unit":"tbsp","notes":"Nutty sauce backbone","category":"Pantry"},{"name":"Sichuan chili oil with sediment","amount":3,"unit":"tbsp","notes":"Aromatic red heat","category":"Pantry"},{"name":"Chinkiang black vinegar & soy sauce","amount":2,"unit":"tbsp","notes":"Malty acid balance","category":"Pantry"},{"name":"Crushed roasted peanuts & scallions","amount":0.5,"unit":"cup","notes":"Garnish","category":"Pantry"}]'::jsonb,
  '[{"step":1,"title":"Crisp Minced Pork with Ya Cai","instruction":"Stir-fry ground pork in 1 tbsp oil on high heat until browned and crispy. Add Sui Mi Ya Cai, Shaoxing wine, and dark soy sauce. Fry 2 mins until fragrant and dry.","time":"5 mins","temp":"High heat","visualCue":"Dark, deeply savory crispy meat bits."},{"step":2,"title":"Whisk Sesame Chili Base","instruction":"In the bottom of each serving bowl, whisk sesame paste, chili oil, soy sauce, black vinegar, Sichuan pepper powder, and 2 tbsp hot noodle water.","time":"2 mins","temp":"Room temp","visualCue":"Lustrous, spicy reddish-brown nutty sauce."},{"step":3,"title":"Boil Noodles","instruction":"Cook fresh noodles in rolling boil for 2 minutes. Drain well and divide into bowls directly over the sauce.","time":"2 mins","temp":"Boiling","visualCue":"Pristine white springy noodles resting on dark sauce."},{"step":4,"title":"Top & Toss at Table","instruction":"Crown with crispy pork mixture, crushed peanuts, and scallions. Toss vigorously with chopsticks right before eating.","time":"1 min","temp":"Hot","visualCue":"Noodles coated in glossy, numbing, fiery sesame sauce."}]'::jsonb,
  '"Chinese toasted sesame paste is made from toasted seeds and is much darker and nuttier than Mediterranean tahini.","Sui Mi Ya Cai gives the essential fermented umami crunch that defines authentic Chengdu Dan Dan."',
