  '[{"name":"Thinly sliced beef chuck or ribeye (shabu-shabu cut)","amount":350,"unit":"g","notes":"Paper-thin slices","category":"Proteins"},{"name":"Yellow sweet onion, sliced 1/4-inch","amount":1,"unit":"large","notes":"Softened in broth","category":"Produce"},{"name":"Japanese dashi stock (kombu & bonito)","amount":1,"unit":"cup","notes":"Umami base","category":"Pantry"},{"name":"Soy sauce, mirin & sake","amount":3,"unit":"tbsp","notes":"1:1:1 sweet savory ratio","category":"Pantry"},{"name":"Steamed Japanese short-grain rice","amount":3,"unit":"cups","notes":"Warm","category":"Pantry"},{"name":"Beni shoga (red pickled ginger) & onsen egg","amount":2,"unit":"servings","notes":"Topping","category":"Produce"}]'::jsonb,
  '[{"step":1,"title":"Simmer Sweet Onions in Dashi","instruction":"Bring dashi stock, soy sauce, mirin, sake, and 1 tbsp sugar to a simmer in a skillet. Add sliced onions and cook 6 minutes until tender and translucent.","time":"6 mins","temp":"Medium heat","visualCue":"Onions turn glossy and absorb brown dashi broth."},{"step":2,"title":"Gently Simmer Thin Beef","instruction":"Add thinly sliced beef ribbons, separating slices so they don''t clump. Simmer gently for 4-5 minutes until beef is just cooked through. Skim any surface foam.","time":"5 mins","temp":"Medium-low heat","visualCue":"Beef turns tender brown and juicy."},{"step":3,"title":"Assemble the Donburi Bowl","instruction":"Mound warm rice into deep bowls. Use slotted spoon to place simmered beef and onions generously over rice. Ladle 3 tbsp savory broth over top. Garnish with red pickled ginger and onsen egg.","time":"2 mins","temp":"Piping hot","visualCue":"Glistening beef ribbons over sauce-soaked rice."}]'::jsonb,
  '"Use paper-thin shabu-shabu beef cut; thick beef turns tough when simmered.","A poached or onsen egg broken over the hot beef creates a rich, creamy sauce with the dashi broth."',
