  '"Carbon steel wok","Wok ladle"',
  '[{"name":"Day-old chilled Jasmine rice (grains separated)","amount":4,"unit":"cups","notes":"Cold & dry","category":"Pantry"},{"name":"Diced Char Siu BBQ pork","amount":150,"unit":"g","notes":"Sweet savory pork cubes","category":"Proteins"},{"name":"Small peeled shrimp","amount":150,"unit":"g","notes":"Deveined","category":"Proteins"},{"name":"Eggs, beaten","amount":3,"unit":"large","notes":"Farm fresh","category":"Dairy"},{"name":"Frozen sweet peas & scallions","amount":1,"unit":"cup","notes":"Vibrant green","category":"Produce"},{"name":"Light soy sauce & Shaoxing wine","amount":2,"unit":"tbsp","notes":"Subtle seasoning","category":"Pantry"},{"name":"Toasted sesame oil & white pepper","amount":1,"unit":"tsp","notes":"Aroma finish","category":"Spices"}]'::jsonb,
  '[{"step":1,"title":"Scramble Eggs in Screaming Wok","instruction":"Heat 2 tbsp oil in smoking wok. Pour in beaten eggs, swirl 10 seconds into soft curds, and immediately add cold rice.","time":"1 min","temp":"High heat","visualCue":"Eggs puff into delicate golden ribbons."},{"step":2,"title":"Break & Toast Rice Grains","instruction":"Press rice with curved back of wok ladle to break up clumps. Toss continuously over intense heat for 3 minutes until grains dance and pop.","time":"3 mins","temp":"High heat","visualCue":"Individual grains separate and pick up egg coating."},{"step":3,"title":"Add Proteins & Vegetables","instruction":"Toss in diced char siu pork, shrimp, and sweet peas. Stir-fry briskly for 2 minutes until shrimp turn pink.","time":"2 mins","temp":"High heat","visualCue":"Colorful medley with sweet roasted pork aroma."},{"step":4,"title":"Wok Rim Seasoning","instruction":"Drizzle light soy sauce around hot wok walls (not directly on rice) to vaporize and infuse smoky wok hei. Toss with sesame oil, white pepper, and scallions.","time":"1 min","temp":"High heat","visualCue":"Fragrant, separate grains with no excess grease."}]'::jsonb,
  '"Always use day-old rice that has dried out in the refrigerator; freshly cooked warm rice turns gummy and clumps when stir-fried.","Pouring soy sauce around the searing hot rim of the wok instantly caramelizes it, creating genuine restaurant wok hei."',
  '[{"original":"Char Siu","alternative":"Diced ham or smoked turkey","notes":"Easy supermarket alternative"}]'::jsonb,
  '[{"mistake":"Drowning rice in dark soy sauce","remedy":"Traditional Yang Chow is pale gold, seasoned lightly with light soy and white pepper."}]'::jsonb,
