  '"Ttukbaegi (Korean earthenware pot) or Dutch oven"',
  '[{"name":"Aged sour Napa cabbage kimchi, chopped","amount":2,"unit":"cups","notes":"Well-fermented with 1/2 cup kimchi brine","category":"Produce"},{"name":"Pork belly or pork shoulder, cut bite-sized","amount":250,"unit":"g","notes":"Sliced","category":"Proteins"},{"name":"Medium or firm tofu, sliced","amount":250,"unit":"g","notes":"Thick rectangles","category":"Proteins"},{"name":"Korean gochugaru (red pepper flakes)","amount":1.5,"unit":"tbsp","notes":"Vibrant red color","category":"Spices"},{"name":"Anchovy kelp stock or chicken broth","amount":3,"unit":"cups","notes":"Deep umami broth","category":"Pantry"},{"name":"Toasted sesame oil & minced garlic","amount":2,"unit":"tbsp","notes":"Aromatics","category":"Pantry"}]'::jsonb,
  '[{"step":1,"title":"Sizzle Pork & Kimchi in Sesame Oil","instruction":"In pot, sauté sliced pork belly and aged kimchi in sesame oil for 5 minutes until pork renders and kimchi softens.","time":"5 mins","temp":"Medium heat","visualCue":"Kimchi turns translucent and oil absorbs bright red color."},{"step":2,"title":"Pour Broth & Kimchi Juice","instruction":"Add anchovy kelp broth, kimchi brine, minced garlic, gochugaru, and splash of soy sauce. Bring to a rolling boil.","time":"5 mins","temp":"High heat","visualCue":"Fiery red bubbling broth."},{"step":3,"title":"Simmer with Soft Tofu","instruction":"Lower heat to medium-low. Arrange sliced tofu across the top. Simmer gently for 15 minutes to let tofu absorb the savory broth.","time":"15 mins","temp":"Medium-low heat","visualCue":"Tofu floats in bubbling red broth with tender pork."},{"step":4,"title":"Scallion Garnish & Serve Hot","instruction":"Scatter generous sliced scallions, remove from heat, and carry bubbling pot straight to table with steamed white rice.","time":"1 min","temp":"Piping hot","visualCue":"Steaming, aromatic spicy red stew."}]'::jsonb,
  '"Use old, sour kimchi that has fermented in the fridge for at least 3-4 weeks; fresh young kimchi lacks the complex acid profile required for true Jjigae.","Pour in half a cup of the kimchi brine directly from the jar for instant concentrated flavor."',
  '[{"original":"Pork belly","alternative":"Canned tuna or king oyster mushrooms","notes":"Tuna Kimchi Jjigae is equally famous in Seoul"}]'::jsonb,
  '[{"mistake":"Using freshly made kimchi","remedy":"Fresh kimchi makes the stew taste bland and watery; only aged kimchi works."}]'::jsonb,
