  '[{"name":"Korean sweet potato glass noodles (Dangmyeon)","amount":250,"unit":"g","notes":"Naturally gluten-free chewy noodles","category":"Pantry"},{"name":"Beef sirloin or ribeye, cut into matchsticks","amount":200,"unit":"g","notes":"Marinated in soy & sesame","category":"Proteins"},{"name":"Fresh baby spinach, blanched","amount":150,"unit":"g","notes":"Squeezed dry & seasoned","category":"Produce"},{"name":"Fresh shiitake mushrooms & carrots, julienned","amount":1.5,"unit":"cups","notes":"Thin strips","category":"Produce"},{"name":"Soy sauce, brown sugar & toasted sesame oil","amount":3,"unit":"tbsp","notes":"Sweet-savory dressing","category":"Pantry"},{"name":"Toasted white sesame seeds","amount":2,"unit":"tbsp","notes":"Garnish","category":"Pantry"}]'::jsonb,
  '[{"step":1,"title":"Boil Dangmyeon Noodles","instruction":"Cook sweet potato noodles in rolling boiling water for 7 minutes until translucent and chewy. Drain, rinse under cold water, and toss with 1 tbsp sesame oil to prevent sticking.","time":"8 mins","temp":"Boiling","visualCue":"Clear, glossy, bouncy noodles."},{"step":2,"title":"Sauté Vegetables & Beef Separately","instruction":"Quickly stir-fry julienned carrots, shiitake mushrooms, and marinated beef in separate pans for 2 minutes each so every ingredient retains its vibrant color and crisp texture.","time":"6 mins","temp":"High heat","visualCue":"Glossy, distinct colorful toppings."},{"step":3,"title":"Toss Noodles with Sweet Soy Dressing","instruction":"In a hot wok, stir-fry boiled noodles with soy sauce and brown sugar for 2 minutes until noodles absorb the sauce and turn glossy brown.","time":"2 mins","temp":"Medium heat","visualCue":"Dark amber noodles shining with savory glaze."},{"step":4,"title":"Combine in Large Bowl","instruction":"Transfer noodles to large mixing bowl. Add sautéed beef, spinach, carrots, mushrooms, and sesame seeds. Toss by hand (with gloves) until beautifully distributed.","time":"2 mins","temp":"Warm","visualCue":"Stunning rainbow noodle tangle."}]'::jsonb,
  '"Dangmyeon noodles are made of 100% sweet potato starch; they remain chewy and springy even when served at room temperature.","Cut noodles with kitchen shears twice after boiling so they are easy to toss and eat."',
  '[{"original":"Beef","alternative":"Sliced king oyster mushrooms","notes":"100% vegetarian Japchae"}]'::jsonb,
  '[{"mistake":"Overcooking the noodles","remedy":"Check at 7 minutes; overcooked glass noodles lose their bouncy snap."}]'::jsonb,
