  '"Hand mixer or stand mixer","9x13 baking dish","Fine mesh sifter"',
  '[{"name":"Italian Savoiardi ladyfinger biscuits","amount":300,"unit":"g","notes":"Crisp egg sponge biscuits","category":"Pantry"},{"name":"Fresh Italian mascarpone cheese","amount":500,"unit":"g","notes":"Chilled","category":"Dairy"},{"name":"Fresh egg yolks","amount":4,"unit":"large","notes":"Room temperature","category":"Dairy"},{"name":"Granulated sugar","amount":100,"unit":"g","notes":"Whisked with yolks","category":"Pantry"},{"name":"Heavy whipping cream","amount":1,"unit":"cup","notes":"Whipped to soft peaks","category":"Dairy"},{"name":"Freshly brewed strong espresso (cooled)","amount":1.5,"unit":"cups","notes":"Rich dark roast","category":"Pantry"},{"name":"Dark rum or Marsala wine","amount":2,"unit":"tbsp","notes":"Aroma lift","category":"Pantry"},{"name":"Dutch-process unsweetened cocoa powder","amount":3,"unit":"tbsp","notes":"For dusting layers","category":"Pantry"}]'::jsonb,
  '[{"step":1,"title":"Whip Mascarpone Cream","instruction":"Whisk egg yolks and sugar with electric mixer for 5 minutes until pale, thick, and ribbon-like. Gently fold in mascarpone and whipped heavy cream until cloud-like and smooth.","time":"8 mins","temp":"Room temp","visualCue":"Pillowy, velvety pale yellow cream."},{"step":2,"title":"Espresso Ladyfinger Dip","instruction":"Mix cooled espresso and rum in shallow dish. Flash-dip each ladyfinger for precisely 1.5 seconds per side (do not soak).","time":"5 mins","temp":"Room temp","visualCue":"Biscuits absorb coffee without becoming soggy or snapping."},{"step":3,"title":"Layer Dish","instruction":"Arrange a single layer of coffee-soaked ladyfingers across bottom of dish. Spread half the mascarpone cream evenly on top. Dust with cocoa powder.","time":"5 mins","temp":"Room temp","visualCue":"Clean geometric white cream layer with dark cocoa dusting."},{"step":4,"title":"Second Layer & Chill","instruction":"Repeat with remaining dipped ladyfingers, top with second layer of mascarpone cream, and dust heavily with cocoa powder. Refrigerate at least 6 hours (preferably overnight).","time":"5 mins + chill","temp":"Refrigerated","visualCue":"Set, sliceable layers where coffee, cream, and cocoa merge into heaven."}]'::jsonb,
  '"Only dip the ladyfingers for 1-2 seconds; they absorb moisture from the mascarpone cream as they chill overnight.","Using a hand mixer to whip the yolks and sugar until pale ensures the sugar crystals dissolve completely."',
  '[{"original":"Dark rum","alternative":"Amaretto or vanilla extract","notes":"Alcohol-free alternative"}]'::jsonb,
  '[{"mistake":"Over-soaking ladyfingers","remedy":"Soggy ladyfingers turn the dessert into coffee soup; quick dunk only."}]'::jsonb,
