),
(
  'boeuf-bourguignon-classic',
  'boeuf-bourguignon-classic',
  'Classic French Boeuf Bourguignon',
  'Slow-braised beef chuck in Burgundy Pinot Noir with smoky lardons, pearl onions & cremini mushrooms',
  'The supreme comfort stew of French culinary canon, perfected by Julia Child and Auguste Escoffier. Well-marbled beef chuck is browned in bacon fat, braised gently for hours in full-bodied red Burgundy wine and beef stock with thyme, carrots, pearl onions, and sautéed butter mushrooms.',
  'European',
  'French',
  '30 mins',
  30,
  '150 mins',
  150,
  '180 mins',
  6,
  'Medium',
  4.97,
