  610,
  '"High-Protein","Comfort Food","Dinner","Signature","One-Pot","French","Vegetarian","European","Nut-Free"',
  '"Heavy cast iron French Dutch oven (Le Creuset style)","Tongs","Slotted spoon"',
  '[{"name":"Beef chuck roast, trimmed & cut into 2-inch cubes","amount":1.2,"unit":"kg","notes":"Patted dry","category":"Proteins"},{"name":"Thick-cut bacon (lardons), cut into matchsticks","amount":200,"unit":"g","notes":"Smoky cure","category":"Proteins"},{"name":"Dry red wine (Burgundy Pinot Noir, Côtes du Rhône)","amount":1,"unit":"bottle","notes":"750ml dry red","category":"Pantry"},{"name":"Rich beef bone stock","amount":2,"unit":"cups","notes":"Deep brown stock","category":"Pantry"},{"name":"Pearl onions, peeled","amount":20,"unit":"whole","notes":"Glazed in butter","category":"Produce"},{"name":"Cremini or button mushrooms, quartered","amount":350,"unit":"g","notes":"Sautéed in butter","category":"Produce"},{"name":"Tomato paste & all-purpose flour","amount":2,"unit":"tbsp","notes":"Thickening roux","category":"Pantry"},{"name":"Fresh thyme sprigs & bay leaf (bouquet garni)","amount":4,"unit":"sprigs","notes":"Tied with twine","category":"Produce"}]'::jsonb,
  '[{"step":1,"title":"Crisp Lardons & Brown Beef","instruction":"Fry bacon matchsticks in Dutch oven until crisp. Remove. In hot rendered fat, sear beef cubes in small batches without crowding until deeply browned on all sides. Remove.","time":"15 mins","temp":"Medium-high heat","visualCue":"Deep mahogany crust on every side of beef."},{"step":2,"title":"Deglaze with Burgundy Wine","instruction":"Sauté sliced carrots and onion in the pot. Stir in tomato paste and flour. Pour in entire bottle of red wine, scraping up all fond from pot bottom. Return beef and bacon with stock and herbs.","time":"10 mins","temp":"High heat","visualCue":"Dark purple wine simmering with scraped flavor crust."},{"step":3,"title":"Slow Oven Braise","instruction":"Cover tightly and transfer to 325°F (165°C) oven for 2.5 hours until beef is melt-in-mouth fork tender.","time":"150 mins","temp":"325°F (165°C)","visualCue":"Beef yields completely when pressed with a fork."},{"step":4,"title":"Fold Sautéed Mushrooms & Pearl Onions","instruction":"In a separate pan, sauté mushrooms and pearl onions in butter until golden brown. Gently fold into the stew for the final 10 minutes of cooking.","time":"10 mins","temp":"Low simmer","visualCue":"Lustrous, deep burgundy glossy sauce coating tender beef and whole glazed onions."}]'::jsonb,
  '"Pat beef cubes completely dry with paper towels before searing; surface moisture creates steam instead of the deep Maillard browning that defines this dish.","Use a wine you would happily drink; cooking concentrates both good flavors and harsh tannins."',
  '[{"original":"Red Burgundy","alternative":"Pinot Noir, Merlot, or Cabernet Sauvignon","notes":"Dry, medium-bodied red"}]'::jsonb,
  '[{"mistake":"Crowding the pan when browning beef","remedy":"Sear in 2-3 batches so the beef fries rather than boils in its own juices."}]'::jsonb,
  '"Gluten"',
  'Dutch oven is extremely heavy and hot when coming out of oven.',
  'Exceptional make-ahead dish; keeps refrigerated for 4 days.',
  'https://images.unsplash.com/photo-1534939561126-855b8675edd7?auto=format&fit=crop&w=1000&q=80',
  false,
