  '[{"name":"Globe eggplants, sliced 1/3-inch thick","amount":3,"unit":"large","notes":"Salted & drained","category":"Produce"},{"name":"San Marzano whole tomatoes, crushed","amount":800,"unit":"g","notes":"Simmered with garlic & basil","category":"Pantry"},{"name":"Fresh mozzarella (fior di latte), torn","amount":300,"unit":"g","notes":"Drained","category":"Dairy"},{"name":"Parmigiano Reggiano, freshly grated","amount":1,"unit":"cup","notes":"Aged 24 months","category":"Dairy"},{"name":"Fresh basil leaves","amount":20,"unit":"leaves","notes":"Whole leaves","category":"Produce"},{"name":"Olive oil for frying","amount":2,"unit":"cups","notes":"High quality oil","category":"Pantry"}]'::jsonb,
  '[{"step":1,"title":"Salt & Fry Eggplant Slices","instruction":"Salt eggplant slices for 20 mins to purge bitterness. Pat completely dry. Fry in hot olive oil for 3 mins per side until deep golden. Drain on paper towels.","time":"15 mins","temp":"360°F (180°C)","visualCue":"Tender, golden brown silky eggplant rounds."},{"step":2,"title":"Simmer Simple Basil Marinara","instruction":"Simmer crushed tomatoes with olive oil, garlic, and fresh basil for 15 minutes until sweet and thick.","time":"15 mins","temp":"Medium heat","visualCue":"Aromatic red tomato sauce."},{"step":3,"title":"Layer Melanzane, Sauce & Cheese","instruction":"Spread sauce on bottom of baking dish. Layer fried eggplant, torn mozzarella, fresh basil, and grated Parmigiano. Repeat for 3 layers, finishing with sauce and cheese on top.","time":"5 mins","temp":"Room temp","visualCue":"Beautiful layered casserole."},{"step":4,"title":"Bake to Golden Bronze","instruction":"Bake at 375°F (190°C) for 30 minutes until bubbling vigorously and crust is golden brown. Rest 15 mins before slicing.","time":"30 mins","temp":"375°F (190°C)","visualCue":"Bubbling red sauce with melted golden cheese gratin."}]'::jsonb,
  '"Salting and pressing the eggplant slices before frying eliminates excess water, ensuring they fry crisp rather than soaking up oil.","Allow the baked parmigiana to rest for 15 minutes so the cheese sets into neat sliceable portions."',
