),
(
  'classic-french-onion-soup',
  'classic-french-onion-soup',
  'Bistro French Caramelized Onion Soup (Soupe à l''Oignon)',
  'Slow-caramelized sweet yellow onions in rich beef bone consommé with toasted baguette & bubbling Gruyère gratin',
  'The soul of Parisian bistro dining. Thinly sliced yellow onions are cooked down patiently for 45 minutes until sweet, jammy, and deep amber brown, deglazed with dry sherry and simmered in rich beef broth, topped with toasted sourdough croutons and melted, bubbling Gruyère cheese.',
  'European',
  'French',
  '15 mins',
  15,
  '55 mins',
  55,
  '70 mins',
  4,
  'Medium',
  4.96,
  390,
  440,
  '"Comfort Food","Soup","Dinner","Signature","Traditional","French","Vegetarian","European","Nut-Free"',
  '"Dutch oven","Oven-safe soup crocks / ramekins","Broiler"',
  '[{"name":"Yellow onions, thinly sliced from root to stem","amount":1.5,"unit":"kg","notes":"Sweet when caramelized","category":"Produce"},{"name":"Rich beef bone stock","amount":6,"unit":"cups","notes":"Deep brown beef broth","category":"Pantry"},{"name":"French Gruyère cheese, grated","amount":200,"unit":"g","notes":"Nutty, excellent melting cheese","category":"Dairy"},{"name":"French baguette or rustic sourdough slices","amount":4,"unit":"thick slices","notes":"Toasted dry","category":"Pantry"},{"name":"Dry sherry or dry white wine","amount":0.5,"unit":"cup","notes":"Deglazing pan","category":"Pantry"},{"name":"Butter & fresh thyme sprigs","amount":3,"unit":"tbsp","notes":"Fat & herbs","category":"Dairy"}]'::jsonb,
  '[{"step":1,"title":"Slow Caramelization of Onions","instruction":"Melt butter in Dutch oven over medium-low heat. Add sliced onions and pinch salt. Cook slowly for 45 minutes, stirring every few minutes, until onions collapse into a deep amber-brown jam.","time":"45 mins","temp":"Low-medium heat","visualCue":"Volume reduces by 80% into dark mahogany sweet jam."},{"step":2,"title":"Deglaze with Sherry","instruction":"Pour in dry sherry, scraping up all dark caramelized sugars (fond) from the pot bottom. Simmer 2 mins until alcohol evaporates.","time":"3 mins","temp":"Medium heat","visualCue":"Pan bottom cleans up completely into the onions."},{"step":3,"title":"Simmer Beef Consommé","instruction":"Add rich beef stock, fresh thyme sprigs, and bay leaf. Simmer uncovered for 20 minutes to meld flavors. Discard thyme sprigs.","time":"20 mins","temp":"Low simmer","visualCue":"Dark, clear amber soup with floating caramelized onion strands."},{"step":4,"title":"Broil the Gruyère Gratin","instruction":"Ladle soup into ovenproof crocks. Float a toasted baguette slice on top, cover generously with grated Gruyère, and broil 4 minutes until cheese is melted, browned, and bubbling.","time":"4 mins","temp":"Broil High","visualCue":"Crisp browned cheese crust draped over edges of the crock."}]'::jsonb,
  '"Patience is the only shortcut: do not rush the onions over high heat; low, slow caramelization breaks down all complex sugars into incredible deep sweetness.","Toast the baguette slices thoroughly dry so they absorb soup like a sponge without disintegrating."',
  '[{"original":"Gruyère","alternative":"Comté or sharp Swiss cheese","notes":"Excellent melting profile"}]'::jsonb,
  '[{"mistake":"Burning the onions on high heat","remedy":"Burnt onions taste bitter; keep heat moderate and stir frequently."}]'::jsonb,
  '"Gluten","Dairy"',
  'Ovenproof crocks come out blisteringly hot from broiler; serve on a plate.',
  'Soup base keeps 5 days in fridge; broil crouton and cheese fresh.',
  'https://images.unsplash.com/photo-1547592166-23ac45744acd?auto=format&fit=crop&w=1000&q=80',
  false,
  '{"servingSize":"1 portion (~368g)","calories":440,"energyKj":1841,"protein":15,"carbohydrates":48,"sugar":6,"fiber":7,"totalFat":15,"saturatedFat":5,"sodium":528}'::jsonb
),
