  '[{"name":"Lasagna pasta sheets (boiled or no-boil)","amount":16,"unit":"sheets","notes":"Egg pasta preferred","category":"Pantry"},{"name":"Traditional Bolognese ragù (beef, pork, wine, milk)","amount":4,"unit":"cups","notes":"Slow-simmered rich meat sauce","category":"Pantry"},{"name":"Silky béchamel sauce (butter, flour, whole milk, nutmeg)","amount":3,"unit":"cups","notes":"Warm & velvety","category":"Dairy"},{"name":"Parmigiano Reggiano, freshly grated","amount":1.5,"unit":"cups","notes":"Aged 24 months","category":"Dairy"}]'::jsonb,
  '[{"step":1,"title":"Prepare Béchamel","instruction":"Melt 50g butter in saucepan, whisk in 50g flour for 2 minutes. Gradually whisk in 3 cups warm milk, pinch salt, and grated nutmeg. Simmer 5 mins until smooth and velvety.","time":"8 mins","temp":"Medium heat","visualCue":"Lustrous white sauce that coats back of spoon."},{"step":2,"title":"Layer Five Times","instruction":"Coat baking dish bottom with béchamel. Lay pasta sheets. Spread layer of meat ragù, drizzle béchamel, and sprinkle Parmigiano. Repeat for 5-6 layers.","time":"10 mins","temp":"Room temp","visualCue":"Alternating red, white, and golden cheese layers."},{"step":3,"title":"Top Layer & Bake","instruction":"Finish top layer with béchamel, a few spoonfuls of ragù swirled in, and heavy snow of Parmigiano. Bake at 375°F (190°C) for 35 mins covered with foil, then 15 mins uncovered until golden and bubbling.","time":"50 mins","temp":"375°F (190°C)","visualCue":"Golden brown blistered cheese crust with bubbling red edges."},{"step":4,"title":"Rest & Slice","instruction":"Rest on counter for 20 minutes before slicing to allow internal layers to set into clean geometric squares.","time":"20 mins","temp":"Resting","visualCue":"Clean, perfect restaurant-style layered cross-section."}]'::jsonb,
  '"Real Bolognese lasagna uses silky béchamel sauce, NOT ricotta cheese; béchamel melts into the meat sauce for authentic creaminess.","Letting the baked lasagna rest for 20 minutes before cutting prevents the layers from sliding apart."',
  '[{"original":"Meat ragù","alternative":"Mushroom, spinach and lentil ragù","notes":"Vegetarian Lasagna"}]'::jsonb,
