  '"Churrero / piping bag with large closed star tip (Wilton 1M)","Deep frying pot","Kitchen shears"',
  '[{"name":"All-purpose flour, sifted","amount":250,"unit":"g","notes":"High quality wheat flour","category":"Pantry"},{"name":"Boiling water with pinch salt & 1 tbsp olive oil","amount":1.25,"unit":"cups","notes":"Scalding water","category":"Pantry"},{"name":"Granulated sugar & ground cinnamon","amount":0.5,"unit":"cup","notes":"For rolling hot churros","category":"Pantry"},{"name":"Spanish bittersweet dark chocolate (70%)","amount":150,"unit":"g","notes":"Chopped fine","category":"Pantry"},{"name":"Whole milk with 1 tsp cornstarch","amount":1,"unit":"cup","notes":"For thick pudding-like dipping sauce","category":"Dairy"},{"name":"Oil for deep frying","amount":3,"unit":"cups","notes":"Neutral vegetable oil","category":"Pantry"}]'::jsonb,
  '[{"step":1,"title":"Scald & Beat Churro Dough","instruction":"Pour boiling salted water with oil directly over flour in a bowl. Beat vigorously with a wooden spoon for 2 minutes until a thick, shiny, cohesive dough forms. Let cool 10 mins.","time":"5 mins","temp":"Room temp","visualCue":"Smooth, dense dough that pulls cleanly away from bowl."},{"step":2,"title":"Make Thick Spanish Dipping Chocolate","instruction":"Simmer milk, cornstarch, and sugar in small saucepan. Whisk in chopped dark chocolate until completely melted, thick, and pudding-like.","time":"5 mins","temp":"Low heat","visualCue":"Lustrous, glossy, thick dark chocolate that coats a spoon."},{"step":3,"title":"Pipe & Snip Directly into Hot Oil","instruction":"Fill piping bag with star nozzle. Pipe 5-inch dough ribbons directly into 375°F (190°C) oil, snipping ends with kitchen shears. Fry 3-4 minutes until golden and crisp.","time":"4 mins","temp":"375°F (190°C)","visualCue":"Fluted ridges turn deep amber gold."},{"step":4,"title":"Roll in Cinnamon Sugar & Dip","instruction":"Drain on paper towels for 30 seconds, roll immediately in cinnamon sugar while warm, and serve with hot dipping chocolate.","time":"2 mins","temp":"Hot","visualCue":"Cinnamon sugar clinging to golden fluted ridges."}]'::jsonb,
  '"Always use a star nozzle (not round); the star ridges allow steam to escape so the churros don't explode in hot oil and produce maximum crispy surface area.","Spanish dipping chocolate uses a little cornstarch to give that rich, spoon-coating pudding texture."',
  '[{"original":"Dark chocolate","alternative":"Dulce de leche or Nutella","notes":"Latin American style"}]'::jsonb,
  '[{"mistake":"Using a smooth round nozzle","remedy":"Round churros can trap steam and burst dangerously in oil; always use star tip."}]'::jsonb,
