  '"Deep pot for frying","Slotted spoon","Saucepan"',
  '[{"name":"Russet potatoes, peeled & cut in 1-inch rough cubes","amount":750,"unit":"g","notes":"High starch for crispness","category":"Produce"},{"name":"Spanish smoked hot paprika (Pimentón picante)","amount":1.5,"unit":"tbsp","notes":"Fiery smoky spice","category":"Spices"},{"name":"Olive oil & flour for roux","amount":2,"unit":"tbsp","notes":"Sauce base","category":"Pantry"},{"name":"Chicken or vegetable broth","amount":1,"unit":"cup","notes":"Warm broth","category":"Pantry"},{"name":"Garlic allioli (mayonnaise, garlic, lemon)","amount":0.5,"unit":"cup","notes":"Creamy topping","category":"Dairy"},{"name":"Frying oil","amount":3,"unit":"cups","notes":"Clean frying oil","category":"Pantry"}]'::jsonb,
  '[{"step":1,"title":"Parboil Potatoes with Baking Soda","instruction":"Boil potato cubes in salted water with 0.5 tsp baking soda for 6 minutes until edges soften slightly. Drain and shake vigorously in pot to create a rough, starchy surface.","time":"8 mins","temp":"Boiling","visualCue":"Potatoes have a fuzzy, craggy starchy surface."},{"step":2,"title":"Simmer Smoky Bravas Sauce","instruction":"Heat olive oil in small pan, stir in flour and smoked pimentón for 1 minute. Gradually whisk in warm broth and simmer 5 minutes until thick and glossy.","time":"6 mins","temp":"Medium heat","visualCue":"Velvety crimson, glossy spicy sauce."},{"step":3,"title":"Double Fry to Glass Crunch","instruction":"Fry potatoes in 360°F oil for 8 minutes until golden amber and shatteringly crisp. Drain on paper towels and salt immediately.","time":"8 mins","temp":"360°F (180°C)","visualCue":"Ultra-crisp golden cubes that crunch audibly."},{"step":4,"title":"Drizzle & Serve","instruction":"Pile hot potatoes in a dish. Spoon spicy bravas sauce over top and crown with a dollop of creamy garlic allioli.","time":"2 mins","temp":"Hot","visualCue":"Golden crunchy potatoes with contrasting red and white sauces."}]'::jsonb,
  '"Boiling with a pinch of baking soda breaks down the surface starches into a mashed paste that fries into an impossibly crispy glass shell.","Authentic Madrid bravas sauce uses no tomatoes; its rich red color and body come purely from smoked pimentón and stock roux."',
  '[{"original":"Allioli","alternative":"Vegan garlic mayo","notes":"100% vegan tapas"}]'::jsonb,
  '[{"mistake":"Skipping the parboil","remedy":"Raw potatoes fried directly will turn chewy instead of shatteringly crisp."}]'::jsonb,
