  '"9x13 metal baking pan","Pastry brush","Clean kitchen towel for spinach squeezing"',
  '[{"name":"Fresh spinach, washed & chopped","amount":600,"unit":"g","notes":"Squeezed bone-dry","category":"Produce"},{"name":"Authentic Greek barrel-aged feta, crumbled","amount":300,"unit":"g","notes":"Tangy sheep milk cheese","category":"Dairy"},{"name":"Filo pastry sheets (thawed)","amount":16,"unit":"sheets","notes":"Tissue thin","category":"Pantry"},{"name":"Fresh dill & scallions, finely chopped","amount":1,"unit":"cup","notes":"Herbal backbone","category":"Produce"},{"name":"Eggs, beaten","amount":2,"unit":"large","notes":"Binder","category":"Dairy"},{"name":"Extra virgin olive oil & melted butter blend","amount":0.75,"unit":"cup","notes":"For brushing pastry","category":"Pantry"}]'::jsonb,
  '[{"step":1,"title":"Squeeze Spinach Bone-Dry","instruction":"Toss chopped spinach with 1 tsp salt, rest 10 mins, then wring out all moisture through a clean towel until completely dry.","time":"10 mins","temp":"Room temp","visualCue":"Small, dry clump of emerald green spinach."},{"step":2,"title":"Mix Savory Herb-Feta Filling","instruction":"Crumble feta into dry spinach with chopped dill, scallions, eggs, pinch nutmeg, and black pepper. Stir gently to combine.","time":"5 mins","temp":"Room temp","visualCue":"Green and white speckled crumbly filling."},{"step":3,"title":"Layer Filo Pastry","instruction":"Brush baking dish with oil. Layer 8 filo sheets, brushing each sheet generously with butter-olive oil blend. Spread spinach-feta filling evenly across center. Top with remaining 8 brushed filo sheets.","time":"10 mins","temp":"Room temp","visualCue":"Neat, crisp pastry stack with filling enclosed."},{"step":4,"title":"Pre-Score & Golden Bake","instruction":"Score top pastry sheets into squares with sharp knife. Bake at 375°F (190°C) for 40 minutes until deeply golden brown and flaky. Rest 10 mins before cutting.","time":"40 mins","temp":"375°F (190°C)","visualCue":"Puffed, blistered golden-amber crust with crackling layers."}]'::jsonb,
  '"Squeezing the spinach completely bone-dry is the most critical step; any residual water will make the bottom filo layers soggy.","Pre-scoring the top filo before baking makes cutting clean, shatter-free slices effortless."',
  '[{"original":"Feta","alternative":"Half feta, half ricotta (Anthotyro)","notes":"Milder, creamier filling"}]'::jsonb,
  '[{"mistake":"Using wet spinach","remedy":"Wring out every drop of water in a tea towel."}]'::jsonb,
