  '"Cast iron skillet or plancha","Blender"',
  '[{"name":"Pork shoulder or tenderloin, thinly sliced","amount":700,"unit":"g","notes":"Cut into 1/4-inch strips","category":"Proteins"},{"name":"Achiote paste block","amount":50,"unit":"g","notes":"Earthy red annatto seasoning","category":"Pantry"},{"name":"Guajillo chiles, stemmed & seeded","amount":3,"unit":"whole","notes":"Soaked in hot water","category":"Spices"},{"name":"Fresh pineapple juice & fresh lime","amount":0.5,"unit":"cup","notes":"Natural fruit enzyme marinade","category":"Produce"},{"name":"Fresh pineapple, sliced into wedges","amount":1,"unit":"cup","notes":"Seared on skillet","category":"Produce"},{"name":"White corn tortillas","amount":12,"unit":"tortillas","notes":"Warmed","category":"Pantry"},{"name":"Finely diced white onion & fresh cilantro","amount":0.75,"unit":"cup","notes":"Street-style taco garnish","category":"Produce"}]'::jsonb,
  '[{"step":1,"title":"Blend Achiote Adobo Marinade","instruction":"Blend soaked guajillo chiles, achiote paste, pineapple juice, lime juice, garlic, cumin, and Mexican oregano into a smooth crimson paste.","time":"5 mins","temp":"Off heat","visualCue":"Thick, deep brick-red aromatic adobo."},{"step":2,"title":"Marinate Pork","instruction":"Coat sliced pork thoroughly in adobo marinade. Chill for at least 2 hours (or overnight) so fruit enzymes tenderize the meat.","time":"10 mins + chill","temp":"Refrigerated","visualCue":"Pork is saturated in vibrant scarlet marinade."},{"step":3,"title":"Sear Meat & Char Pineapple","instruction":"Get a cast iron skillet screaming hot with a drizzle of oil. Sear marinated pork in batches until charred at edges. In the same pan, sear pineapple slices until blackened in spots.","time":"10 mins","temp":"High heat","visualCue":"Crisp caramelized edges with smoky sweet pineapple char."},{"step":4,"title":"Assemble on Warm Corn Tortillas","instruction":"Warm corn tortillas on dry skillet. Fill with seared pork, diced charred pineapple, white onion, cilantro, and a squeeze of fresh lime.","time":"5 mins","temp":"Warm","visualCue":"Vibrant street tacos with contrasting red pork, yellow pineapple, and green cilantro."}]'::jsonb,
  '"Pineapple contains bromelain, a natural enzyme that tenderizes pork shoulder; don't marinate for more than 12 hours or the meat can become too soft.","Searing on a blazing hot cast-iron skillet replicates the char of a traditional vertical trompo spit."',
  '[{"original":"Pork shoulder","alternative":"Chicken thighs or firm pressed tofu","notes":"Poultry or plant-based variation"}]'::jsonb,
  '[{"mistake":"Serving on cold corn tortillas","remedy":"Cold corn tortillas crack and tear; always warm on a hot comal or dry skillet until pliable."}]'::jsonb,
