(
  'birria-de-res-tacos-consome',
  'birria-de-res-tacos-consome',
  'Jalisco Birria de Res Tacos con Consomé',
  'Slow-braised beef chuck & short ribs in guajillo-ancho chile broth with crispy dipped corn tortillas & melted Oaxaca cheese',
  'The viral sensation hailing from Jalisco, Mexico. Beef chuck and bone-in short ribs are slow-braised for hours in an aromatic broth of toasted dried chiles, cinnamon, cloves, and tomatoes until fall-apart tender. Tortillas are dipped in the rendered beef chili fat, griddled with Oaxaca cheese, filled with shredded beef, and served with a bowl of rich consomé for dipping.',
  'Mexican',
  'Mexican',
  '30 mins',
  30,
  '120 mins',
  120,
  '150 mins',
  6,
  'Medium',
  4.99,
  540,
  680,
  '"High-Protein","Gluten-Free","Street Food","Dinner","Signature","Mexican","Vegetarian","Nut-Free"',
  '"Dutch oven or slow cooker","Comal / flat griddle","Tongs"',
  '[{"name":"Beef chuck roast & bone-in short ribs","amount":1.2,"unit":"kg","notes":"Cut into large chunks","category":"Proteins"},{"name":"Dried Guajillo & Ancho chiles","amount":6,"unit":"whole","notes":"Stemmed & seeded","category":"Spices"},{"name":"Canned crushed fire-roasted tomatoes","amount":400,"unit":"g","notes":"Rich base","category":"Pantry"},{"name":"Mexican cinnamon stick, cloves & Mexican oregano","amount":1,"unit":"tbsp","notes":"Aromatics","category":"Spices"},{"name":"Apple cider vinegar","amount":3,"unit":"tbsp","notes":"Acidity lift","category":"Pantry"},{"name":"Oaxaca or Monterey Jack cheese, shredded","amount":300,"unit":"g","notes":"Meltable string cheese","category":"Dairy"},{"name":"Corn tortillas","amount":16,"unit":"tortillas","notes":"Dipped in broth fat","category":"Pantry"},{"name":"Limes, chopped white onions & cilantro","amount":1,"unit":"serving","notes":"For dipping bowl garnish","category":"Produce"}]'::jsonb,
  '[{"step":1,"title":"Toast & Rehydrate Chiles","instruction":"Toast dried guajillo and ancho chiles on dry skillet for 1 minute. Transfer to a bowl with hot water for 15 minutes to soften.","time":"15 mins","temp":"Off heat","visualCue":"Pliable, deep mahogany softened chiles."},{"step":2,"title":"Blend Birria Adobo","instruction":"Blend softened chiles with tomatoes, vinegar, garlic, cinnamon, oregano, cumin, and 1 cup chile soaking water until completely smooth. Strain through a sieve.","time":"5 mins","temp":"Off heat","visualCue":"Silky, deep crimson adobo sauce."},{"step":3,"title":"Slow Braise to Fall-Apart Tenderness","instruction":"Sear beef in pot. Pour adobo and beef broth over meat. Cover and simmer on low for 2 hours (or pressure cook 45 mins) until beef shreds effortlessly. Skim red fat from surface into a bowl.","time":"120 mins","temp":"Low simmer","visualCue":"Meat shreds with two forks; rich red consomé broth."},{"step":4,"title":"Dip, Griddle & Serve Quesabirria","instruction":"Dip corn tortillas into reserved surface fat. Place on hot griddle, top with shredded cheese and pulled beef. Fold in half and cook until crisp and golden on both sides. Serve with cups of hot consomé for dipping.","time":"8 mins","temp":"Medium-high heat","visualCue":"Crunchy red-stained tortillas with melted cheese pull and steamy broth."}]'::jsonb,
  '"Skim the red chili-infused tallow from the surface of the braise; dipping the tortillas into this fat before griddling is the non-negotiable secret to crispy, flavorful quesabirria.","Serve the consomé in small coffee mugs so guests can sip between bites."',
  '[{"original":"Beef short ribs","alternative":"Lamb shoulder or goat meat","notes":"Traditional Jalisco style (Birria de Chivo)"}]'::jsonb,
  '[{"mistake":"Discarding the braising broth","remedy":"The consomé IS the highlight of the meal; never drain or discard it."}]'::jsonb,
  '"Dairy"',
  'Steam inside Dutch oven is intensely hot; vent carefully.',
  'Shredded beef and consomé freeze for up to 3 months.',
  'https://images.unsplash.com/photo-1565299585323-38d6b0865b47?auto=format&fit=crop&w=1000&q=80',
  false,
