  '"Molcajete (volcanic stone mortar) or mixing bowl","Fork or pestle"',
  '[{"name":"Ripe Hass avocados","amount":4,"unit":"large","notes":"Yields gently to thumb pressure","category":"Produce"},{"name":"Serrano or jalapeño pepper, finely minced","amount":2,"unit":"whole","notes":"Seeds removed for mild heat","category":"Produce"},{"name":"White onion, finely diced","amount":0.5,"unit":"medium","notes":"Crisp bite","category":"Produce"},{"name":"Fresh cilantro leaves, chopped","amount":0.5,"unit":"cup","notes":"Tender stems and leaves","category":"Produce"},{"name":"Fresh lime juice","amount":2,"unit":"tbsp","notes":"Prevents browning & adds acid","category":"Produce"},{"name":"Coarse sea salt (kosher)","amount":1,"unit":"tsp","notes":"To taste","category":"Pantry"},{"name":"Corn tortillas cut into triangles (totopos)","amount":8,"unit":"tortillas","notes":"Fried golden in oil","category":"Pantry"}]'::jsonb,
  '[{"step":1,"title":"Pound Aromatics into Paste","instruction":"In molcajete (or bowl), mash minced onion, serrano chile, cilantro, and sea salt with pestle until juicy and aromatic.","time":"3 mins","temp":"Room temp","visualCue":"Aromatic green-flecked pungent paste."},{"step":2,"title":"Coarsely Mash Avocados","instruction":"Halve avocados, remove pits, and scoop flesh into molcajete. Mash with pestle or fork, keeping pleasant rustic avocado chunks throughout.","time":"3 mins","temp":"Room temp","visualCue":"Lush creamy green with visible avocado chunks."},{"step":3,"title":"Fold Lime & Season","instruction":"Squeeze in fresh lime juice and gently fold with a spoon. Taste and adjust salt or lime as needed.","time":"1 min","temp":"Room temp","visualCue":"Vibrant, glossy lime-flecked guacamole."},{"step":4,"title":"Fry Warm Totopos","instruction":"Fry corn tortilla wedges in 365°F oil for 2 minutes until crisp and golden. Drain, sprinkle immediately with flaky sea salt, and serve warm with guacamole.","time":"5 mins","temp":"365°F (185°C)","visualCue":"Shatteringly crisp golden chips."}]'::jsonb,
  '"Pounding the onion, chile, and salt first releases the aromatics' cell wall juices, seasoning the avocados uniformly.","Never puree guacamole in a food processor; the texture must be chunky and rustic."',
  '[{"original":"Serrano chile","alternative":"Jalapeño or poblano","notes":"For milder heat"}]'::jsonb,
  '[{"mistake":"Using rock-hard or overripe black avocados","remedy":"Use avocados that yield gently like ripe peaches."}]'::jsonb,
