  '"Deep fryer or Dutch oven","Belgian waffle maker","Wire rack"',
  '[{"name":"Boneless skinless chicken thighs","amount":750,"unit":"g","notes":"Brined in buttermilk","category":"Proteins"},{"name":"Cultured buttermilk & hot sauce","amount":1.5,"unit":"cups","notes":"Tenderizing marinade","category":"Dairy"},{"name":"All-purpose flour & cornstarch blend","amount":2,"unit":"cups","notes":"3:1 ratio for extreme crispness","category":"Pantry"},{"name":"Paprika, garlic powder, onion powder & cayenne","amount":2,"unit":"tbsp","notes":"Southern spice dredge","category":"Spices"},{"name":"Belgian waffle batter","amount":4,"unit":"servings","notes":"Malted, fluffy","category":"Pantry"},{"name":"Hot honey (honey infused with cayenne and chili flakes)","amount":0.5,"unit":"cup","notes":"Warm drizzle","category":"Pantry"}]'::jsonb,
  '[{"step":1,"title":"Buttermilk Brine","instruction":"Submerge chicken thighs in buttermilk, hot sauce, salt, and garlic powder for at least 3 hours.","time":"10 mins + chill","temp":"Refrigerated","visualCue":"Chicken absorbs buttermilk acidity."},{"step":2,"title":"Shaggy Dredge","instruction":"Dredge chicken in seasoned flour-cornstarch mix. Drizzle 3 tbsp buttermilk marinade into flour and squeeze to create craggy ''shags'' that fry into extra crunch.","time":"8 mins","temp":"Room temp","visualCue":"Rough, craggy textured coating on chicken."},{"step":3,"title":"Golden Deep Fry","instruction":"Fry chicken in 350°F (175°C) oil for 10-12 minutes until internal temp reaches 165°F and crust is deep golden brown. Drain on wire rack.","time":"12 mins","temp":"350°F (175°C)","visualCue":"Shatteringly crisp, deep amber craggy crust."},{"step":4,"title":"Griddle Waffles & Assemble","instruction":"Cook waffles until crisp outside and fluffy inside. Place hot fried chicken over waffle, drizzle generously with warm hot honey, and serve with salted butter.","time":"5 mins","temp":"Hot","visualCue":"Steaming golden waffle topped with glossy glistening fried chicken."}]'::jsonb,
  '"Adding 3 tablespoons of the liquid marinade into the dry flour creates craggy nuggets that turn into super-crisp crunch pockets when fried.","Cornstarch in the flour dredge prevents gluten development and keeps the batter light and crackly."',
  '[{"original":"Chicken thighs","alternative":"Chicken breast tenders or fried oyster mushrooms","notes":"White meat or vegetarian"}]'::jsonb,
  '[{"mistake":"Frying in oil that is too hot (>375°F)","remedy":"Exterior will burn before the thick chicken thigh is cooked through; maintain 350°F."}]'::jsonb,
