  '[{"name":"Fresh green tomatillos, husked & halved","amount":500,"unit":"g","notes":"Roasted under broiler","category":"Produce"},{"name":"Serrano peppers & garlic cloves","amount":2,"unit":"peppers","notes":"Broiled with tomatillos","category":"Produce"},{"name":"Mexican crema or sour cream","amount":0.75,"unit":"cup","notes":"Whisked into green salsa","category":"Dairy"},{"name":"Shredded cooked chicken breast","amount":400,"unit":"g","notes":"Seasoned","category":"Proteins"},{"name":"Corn tortillas (softened in warm oil)","amount":12,"unit":"tortillas","notes":"Pliable","category":"Pantry"},{"name":"Swiss cheese & Monterey Jack, shredded","amount":250,"unit":"g","notes":"Melted on top","category":"Dairy"}]'::jsonb,
  '[{"step":1,"title":"Broil Green Salsa Aromatics","instruction":"Broil tomatillos, serrano peppers, onion, and garlic for 7 minutes until blistered and blackened in spots. Blend with cilantro, salt, and Mexican crema until smooth.","time":"10 mins","temp":"Broil High","visualCue":"Creamy, pastel green tangy sauce."},{"step":2,"title":"Soft-Fry Corn Tortillas","instruction":"Dip each corn tortilla in warm oil for 5 seconds to soften so they roll without cracking. Drain.","time":"3 mins","temp":"Medium heat","visualCue":"Pliable, flexible tortillas."},{"step":3,"title":"Roll & Arrange","instruction":"Roll shredded chicken inside tortillas and place seam-side down in baking dish. Pour creamy roasted tomatillo sauce generously over all rolls.","time":"5 mins","temp":"Room temp","visualCue":"Neat rows of rolled tortillas submerged in green sauce."},{"step":4,"title":"Bake to Molten Perfection","instruction":"Cover with shredded cheeses. Bake at 375°F (190°C) for 20 minutes until cheese is completely melted and bubbling at edges with golden brown spots.","time":"20 mins","temp":"375°F (190°C)","visualCue":"Bubbling cheese blanket over tangy green sauce."}]'::jsonb,
