  '[{"name":"Dried chickpeas (soaked overnight with pinch baking soda)","amount":250,"unit":"g","notes":"Cooked until mushy","category":"Pantry"},{"name":"Artisanal sesame tahini paste","amount":0.75,"unit":"cup","notes":"High quality light tahini","category":"Pantry"},{"name":"Fresh lemon juice","amount":0.3,"unit":"cup","notes":"Freshly squeezed","category":"Produce"},{"name":"Ice water or ice cubes","amount":0.5,"unit":"cup","notes":"Secret to pale fluffy silk","category":"Pantry"},{"name":"Garlic cloves, crushed","amount":2,"unit":"cloves","notes":"Mellow garlic","category":"Produce"},{"name":"Toasted pine nuts & za''atar seasoning","amount":3,"unit":"tbsp","notes":"Crunchy topping","category":"Pantry"},{"name":"Extra virgin olive oil","amount":4,"unit":"tbsp","notes":"Poured generously into center","category":"Pantry"}]'::jsonb,
  '[{"step":1,"title":"Overcook Chickpeas with Baking Soda","instruction":"Simmer soaked chickpeas with 1 tsp baking soda in 5 cups water for 30 minutes until skins dissolve and chickpeas can be crushed easily with your tongue.","time":"30 mins","temp":"Medium heat","visualCue":"Soft, falling-apart chickpeas with loose skins."},{"step":2,"title":"Whip Tahini & Lemon First","instruction":"In food processor, whip tahini, lemon juice, garlic, and salt for 2 minutes until it seizes and turns into an airy, pale ivory paste.","time":"2 mins","temp":"Room temp","visualCue":"Thick, whipped pale fluff."},{"step":3,"title":"Add Warm Chickpeas & Ice Water","instruction":"Add warm drained chickpeas and drizzle in ice water while running on high for 4 minutes until impossibly smooth and glossy.","time":"4 mins","temp":"Room temp","visualCue":"Silk-smooth, cloud-like pale emulsion with zero graininess."},{"step":4,"title":"Garnish with Oil Well & Nuts","instruction":"Spoon into shallow bowl, swirl a deep circular well with back of spoon, pour extra virgin olive oil, and scatter toasted pine nuts, paprika, and za''atar.","time":"2 mins","temp":"Room temp","visualCue":"Lustrous olive oil pool cradled in creamy swirls."}]'::jsonb,
  '"Baking soda breaks down the chickpea pectin and skins completely, which is the singular secret to restaurant-level silky texture.","Drizzling ice water into the whipped tahini emulsifies the fats into a cloud-like texture."',
