  '"Food processor","Falafel scoop or cookie scoop","Deep frying pot"',
  '[{"name":"Dried chickpeas (soaked 18 hours in cold water)","amount":300,"unit":"g","notes":"Raw soaked, NEVER canned","category":"Pantry"},{"name":"Fresh flat-leaf parsley & cilantro leaves","amount":2,"unit":"cups","notes":"Packed herbs for vivid green center","category":"Produce"},{"name":"Fresh dill sprigs & scallions","amount":0.5,"unit":"cup","notes":"Herbal depth","category":"Produce"},{"name":"Ground cumin & ground coriander","amount":2,"unit":"tbsp","notes":"Toasted","category":"Spices"},{"name":"Baking powder","amount":0.75,"unit":"tsp","notes":"For airy interior rise","category":"Pantry"},{"name":"Sesame seeds (for rolling exterior)","amount":3,"unit":"tbsp","notes":"Crunchy shell","category":"Pantry"},{"name":"Frying oil","amount":3,"unit":"cups","notes":"Clean vegetable oil","category":"Pantry"}]'::jsonb,
  '[{"step":1,"title":"Pulse Raw Chickpeas with Herbs","instruction":"Pulse drained raw chickpeas, herbs, garlic, scallions, cumin, coriander, salt, and black pepper in food processor until it resembles coarse wet sand (not paste). Chill 30 mins.","time":"8 mins + chill","temp":"Refrigerated","visualCue":"Vibrant emerald green, granular sandy texture."},{"step":2,"title":"Shape with Sesame Crust","instruction":"Stir in baking powder. Shape into 1.5-inch round patties using a falafel tool or hands. Press exterior into sesame seeds.","time":"5 mins","temp":"Room temp","visualCue":"Even green patties coated in white sesame."},{"step":3,"title":"Crispy Golden Deep Fry","instruction":"Fry in 360°F (180°C) oil for 3-4 minutes until deep golden brown on outside. Drain on paper towels.","time":"4 mins","temp":"360°F (180°C)","visualCue":"Dark russet-brown crispy crust."},{"step":4,"title":"Serve in Warm Pita","instruction":"Crack open to reveal steaming, fragrant emerald green interior. Serve in warm pita with chopped salad, pickles, and lemon tahini sauce.","time":"2 mins","temp":"Hot","visualCue":"Shatteringly crisp shell giving way to herb-scented green sponge."}]'::jsonb,
  '"NEVER use canned chickpeas; canned chickpeas contain too much moisture and disintegrate into oil mush. Only raw soaked chickpeas work.","Baking powder creates internal steam pockets for an airy, fluffy sponge instead of a dense hockey puck."',
  '[{"original":"Sesame seeds","alternative":"Cracked coriander seeds on exterior","notes":"Aromatic crust"}]'::jsonb,
  '[{"mistake":"Pureeing the mixture too smooth into paste","remedy":"Pulse to coarse sand consistency; over-processing makes dense, heavy falafel."}]'::jsonb,
