  '[{"name":"Filo pastry sheets (thawed)","amount":1,"unit":"pack (450g)","notes":"Tissue thin","category":"Pantry"},{"name":"Gaziantep raw green pistachios, finely crushed","amount":350,"unit":"g","notes":"Vibrant emerald pistachios","category":"Pantry"},{"name":"Clarified butter (ghee), melted","amount":250,"unit":"g","notes":"Warm","category":"Dairy"},{"name":"Granulated sugar & water","amount":1.5,"unit":"cups","notes":"For soaking syrup","category":"Pantry"},{"name":"Orange blossom water & lemon juice","amount":1,"unit":"tbsp","notes":"Citrus floral aroma","category":"Pantry"}]'::jsonb,
  '[{"step":1,"title":"Boil Citrus Blossom Syrup","instruction":"Simmer sugar, water, and lemon juice for 12 minutes until slightly thick. Stir in orange blossom water and cool completely to room temperature.","time":"15 mins","temp":"Medium heat","visualCue":"Clear, glossy aromatic syrup."},{"step":2,"title":"Layer Buttered Filo & Pistachios","instruction":"Brush pan with butter. Layer 20 filo sheets, brushing each sheet thoroughly with clarified butter. Spread crushed emerald pistachios evenly across center. Top with remaining 20 buttered filo sheets.","time":"20 mins","temp":"Room temp","visualCue":"Tidy, multi-layered golden filo stack."},{"step":3,"title":"Pre-Cut Diamonds & Bake","instruction":"Using a razor-sharp knife, cut pastry into diamond shapes all the way to bottom of pan. Bake at 325°F (165°C) for 45 minutes until golden bronze and crisp.","time":"45 mins","temp":"325°F (165°C)","visualCue":"Puffed, golden-amber wafer layers."},{"step":4,"title":"The Hot-Cold Syrup Sizzle","instruction":"Pour cooled syrup immediately over piping hot baked baklava. Listen to the loud crackling sizzle as the pastry drinks the syrup. Rest 4 hours before serving.","time":"5 mins + rest","temp":"Hot pastry / Cold syrup","visualCue":"Audible crackle; layers stay crisp while bottom glistens with syrup."}]'::jsonb,
  '"The immutable rule of baklava: Pour cold syrup over boiling-hot pastry (or boiling syrup over cold pastry); pouring hot on hot results in soggy pastry.","Clarified butter (with milk solids removed) prevents burning during the long 45-minute bake."',
  '[{"original":"Pistachios","alternative":"Walnuts with a pinch of cinnamon","notes":"Classic Greek style"}]'::jsonb,
  '[{"mistake":"Cutting after baking","remedy":"Always slice into diamonds before baking; baked filo shatters into dust if cut afterwards."}]'::jsonb,
