  '"Clay Tagine or Dutch oven"',
  '[{"name":"Bone-in lamb shanks or shoulder chunks","amount":900,"unit":"g","notes":"Trimmed","category":"Proteins"},{"name":"Pitted sweet prunes","amount":1.5,"unit":"cups","notes":"Glazed in honey & cinnamon","category":"Produce"},{"name":"Moroccan Ras el Hanout & ground ginger","amount":2,"unit":"tbsp","notes":"Fragrant blend","category":"Spices"},{"name":"Saffron threads steeped in warm water","amount":1,"unit":"pinch","notes":"Golden hue","category":"Spices"},{"name":"Raw honey & ground cinnamon","amount":2,"unit":"tbsp","notes":"Prune glaze","category":"Pantry"},{"name":"Blanched slivered almonds, fried golden","amount":0.5,"unit":"cup","notes":"Nutty crunch","category":"Pantry"}]'::jsonb,
  '[{"step":1,"title":"Sear Lamb with Spices","instruction":"Brown lamb pieces in olive oil with chopped onions, ginger, ras el hanout, saffron, and cinnamon stick for 10 minutes until deeply aromatic.","time":"10 mins","temp":"Medium heat","visualCue":"Golden-brown meat with fragrant spice crust."},{"step":2,"title":"Slow Braise in Tagine","instruction":"Add 1.5 cups water, cover with conical lid, and simmer on lowest heat for 60 minutes until lamb is completely tender.","time":"60 mins","temp":"Low simmer","visualCue":"Meat pulls away from bone easily in golden sauce."},{"step":3,"title":"Glaze Prunes in Honey Cinnamon","instruction":"In small saucepan, simmer prunes with 0.5 cup tagine broth, honey, and cinnamon for 8 minutes until plump, glossy, and caramelized.","time":"8 mins","temp":"Medium heat","visualCue":"Glossy, mahogany sweet glazed prunes."},{"step":4,"title":"Garnish & Serve","instruction":"Arrange glazed prunes over tender lamb, spoon rich sauce over, and scatter toasted almonds and sesame seeds. Serve with warm crusty bread.","time":"2 mins","temp":"Hot","visualCue":"Regal clay tagine presentation with glistening sweet prunes and crunchy nuts."}]'::jsonb,
  '"Glazing the prunes separately in honey and broth before adding to the tagine keeps the fruit intact and prevents the main lamb gravy from becoming overly sweet.","The conical lid of the tagine continuously condenses rising steam back down onto the meat."',
