  '[{"name":"Wide knife-cut or ramen wheat noodles","amount":250,"unit":"g","notes":"Chewy flat noodles","category":"Pantry"},{"name":"Garlic cloves, finely minced","amount":4,"unit":"cloves","notes":"Heaped mound","category":"Produce"},{"name":"Scallions, finely chopped","amount":3,"unit":"stalks","notes":"White and green parts","category":"Produce"},{"name":"Coarse chili flakes (Gochugaru or Sichuan)","amount":1.5,"unit":"tbsp","notes":"Bright red","category":"Spices"},{"name":"Chinkiang black vinegar & light soy sauce","amount":2,"unit":"tbsp","notes":"Savory-tangy base","category":"Pantry"},{"name":"Neutral oil + 1 tsp toasted sesame oil","amount":3,"unit":"tbsp","notes":"Heated to smoking point","category":"Pantry"}]'::jsonb,
  '[{"step":1,"title":"Boil Chewy Noodles","instruction":"Cook flat noodles in rolling boiling water for 3-4 minutes until chewy al dente. Drain well and transfer to heatproof serving bowls.","time":"4 mins","temp":"Boiling","visualCue":"Glossy, chewy ribbon noodles."},{"step":2,"title":"Pile Aromatics on Top","instruction":"Drizzle soy sauce and black vinegar around the noodles. Heap minced garlic, chili flakes, scallions, and roasted sesame seeds in a tight mound right in the center.","time":"1 min","temp":"Room temp","visualCue":"A neat colorful mountain of raw aromatics."},{"step":3,"title":"Pour Smoking-Hot Sizzling Oil","instruction":"Heat oil in small pan until lightly smoking (375°F). Carefully pour the smoking oil directly over the garlic-chili mound. Listen to the intense sizzling crackle!","time":"1 min","temp":"375°F (190°C)","visualCue":"Violent crackling sizzle as oil flash-fries garlic and turns chili crimson."},{"step":4,"title":"Toss & Slurp","instruction":"Toss vigorously with chopsticks until noodles are thoroughly coated in glossy, fragrant chili garlic oil.","time":"1 min","temp":"Hot","visualCue":"Glistening red-lacquered noodles with garlic and scallions."}]'::jsonb,
  '"Pour the oil while smoking hot directly over the raw garlic and chili; this cooks out the raw sulfur bite of garlic and infuses the oil instantly.","Wide, ruffled knife-cut noodles catch the chili oil pockets far better than thin noodles."',
