  '[{"name":"Boneless chicken breasts, sliced into strips","amount":450,"unit":"g","notes":"Italian seasoned","category":"Proteins"},{"name":"Penne rigate pasta (dry)","amount":300,"unit":"g","notes":"Cooks directly in sauce","category":"Pantry"},{"name":"Sun-dried tomatoes in oil, sliced","amount":0.5,"unit":"cup","notes":"Sweet tangy bite","category":"Pantry"},{"name":"Fresh baby spinach","amount":2,"unit":"cups","notes":"Wilted at finish","category":"Produce"},{"name":"Chicken broth & heavy cream","amount":3,"unit":"cups","notes":"2 cups broth + 1 cup cream","category":"Dairy"},{"name":"Garlic cloves, minced","amount":4,"unit":"cloves","notes":"Aromatics","category":"Produce"},{"name":"Parmigiano Reggiano, freshly grated","amount":0.75,"unit":"cup","notes":"Stirred into sauce","category":"Dairy"}]'::jsonb,
  '[{"step":1,"title":"Sear Chicken Strips","instruction":"Heat 1 tbsp sun-dried tomato oil in skillet. Sear seasoned chicken strips on high for 5 minutes until golden brown. Remove to plate.","time":"5 mins","temp":"Medium-high heat","visualCue":"Golden brown seared edges."},{"step":2,"title":"Simmer Pasta in Broth & Cream","instruction":"In same skillet, add garlic, sun-dried tomatoes, dry penne, chicken broth, and heavy cream. Bring to boil, cover, and simmer 10 minutes, stirring occasionally.","time":"10 mins","temp":"Medium heat","visualCue":"Penne absorbs liquid and turns tender as starch thickens sauce."},{"step":3,"title":"Fold Spinach, Cheese & Chicken","instruction":"Stir in grated parmesan cheese, fresh baby spinach, and cooked chicken. Simmer 2 minutes until spinach wilts and sauce turns velvety.","time":"2 mins","temp":"Low heat","visualCue":"Creamy, glossy sauce coating al dente penne with melted cheese ribbons."}]'::jsonb,
  '"Cooking the pasta directly in the broth and cream releases pasta starch into the sauce, creating a restaurant-velvet texture without needing flour.","Use the fragrant oil from the sun-dried tomato jar to sear the chicken for extra flavor."',
