  '"Non-stick skillet or wok","Wooden spatula"',
  '[{"name":"Fresh paneer, coarsely crumbled by hand","amount":300,"unit":"g","notes":"High protein cottage cheese","category":"Dairy"},{"name":"Red onion, finely diced","amount":1,"unit":"medium","notes":"Sautéed golden","category":"Produce"},{"name":"Ripe tomatoes, finely chopped","amount":2,"unit":"medium","notes":"Juicy","category":"Produce"},{"name":"Ginger, garlic & green chili, minced","amount":2,"unit":"tbsp","notes":"Fresh piquant base","category":"Produce"},{"name":"Turmeric, cumin & pav bhaji masala","amount":1,"unit":"tbsp","notes":"Spiced seasoning","category":"Spices"},{"name":"Desi ghee or butter","amount":1.5,"unit":"tbsp","notes":"For skillet searing","category":"Dairy"},{"name":"Fresh cilantro leaves & lemon juice","amount":2,"unit":"tbsp","notes":"Bright finish","category":"Produce"}]'::jsonb,
  '[{"step":1,"title":"Sauté Aromatics","instruction":"Melt ghee in skillet over medium-high heat. Add cumin seeds, minced ginger, garlic, green chilies, and onions. Sauté 3 mins until soft and golden.","time":"3 mins","temp":"Medium-high heat","visualCue":"Fragrant sizzling onions and garlic."},{"step":2,"title":"Break Down Tomatoes & Spices","instruction":"Add chopped tomatoes, turmeric, pav bhaji masala, and salt. Cook 3 mins, pressing tomatoes with spatula until soft and saucy.","time":"3 mins","temp":"Medium heat","visualCue":"Glossy spiced tomato base with released juices."},{"step":3,"title":"Fold Crumbled Paneer","instruction":"Add hand-crumbled paneer. Toss briskly for 2 minutes to heat through and absorb spices. Do not overcook or paneer releases water and becomes chewy.","time":"2 mins","temp":"Medium heat","visualCue":"Vibrant yellow-orange scrambled paneer."},{"step":4,"title":"Garnish & Serve with Toast","instruction":"Turn off heat, squeeze fresh lemon juice, scatter chopped cilantro, and serve hot with buttered sourdough toast.","time":"1 min","temp":"Hot","visualCue":"Fluffy, fragrant spiced paneer scramble."}]'::jsonb,
  '"Crumble the paneer by hand instead of grating; uneven rustic curds give a much juicier texture than uniform grated shreds.","Cook paneer for no more than 2 minutes in the pan; excess cooking draws out moisture and turns it dry."',
  '[{"original":"Paneer","alternative":"Firm pressed tofu (Tofu Bhurji) or 4 whole eggs (Akuri)","notes":"Vegan or egg variation"}]'::jsonb,
  '[{"mistake":"Overcooking the paneer","remedy":"Only cook until warmed through; paneer becomes rubbery if fried too long."}]'::jsonb,
