  '"Non-stick skillet","Mixing bowl"',
  '[{"name":"Extra-firm tofu, pressed & cut into 3/4-inch cubes","amount":400,"unit":"g","notes":"Patted dry","category":"Proteins"},{"name":"Cornstarch","amount":2,"unit":"tbsp","notes":"For crunchy crust","category":"Pantry"},{"name":"Toasted sesame oil & soy sauce","amount":2,"unit":"tbsp","notes":"Glaze base","category":"Pantry"},{"name":"Steamed edamame & sliced ripe avocado","amount":1,"unit":"cup","notes":"Nourishing toppings","category":"Produce"},{"name":"Cooked brown rice or sushi rice","amount":2,"unit":"cups","notes":"Warm","category":"Pantry"},{"name":"Sesame seeds & spicy sriracha mayo","amount":2,"unit":"tbsp","notes":"Garnish","category":"Pantry"}]'::jsonb,
  '[{"step":1,"title":"Dust Tofu in Cornstarch","instruction":"Toss dry tofu cubes with cornstarch and pinch salt until evenly coated in a thin powdery veil.","time":"2 mins","temp":"Room temp","visualCue":"Even white powdery coating."},{"step":2,"title":"Pan-Sear to Shattering Crunch","instruction":"Heat 2 tbsp sesame oil in skillet on medium-high. Sear tofu cubes for 6-8 minutes, turning with tongs until all 6 sides are crispy golden brown.","time":"8 mins","temp":"Medium-high heat","visualCue":"Golden brown crisp shell with soft interior."},{"step":3,"title":"Glaze in Soy Ginger Sauce","instruction":"Drizzle soy sauce, maple syrup, and minced ginger over hot tofu. Toss 30 seconds until sauce bubbles into a sticky, glossy lacquer.","time":"1 min","temp":"Medium heat","visualCue":"Glistening amber glaze clinging to crispy tofu."},{"step":4,"title":"Assemble Poke Bowl","instruction":"Mound warm rice in bowls. Arrange glazed crispy tofu, creamy avocado, edamame, and carrots. Drizzle with sriracha mayo and sesame seeds.","time":"2 mins","temp":"Warm","visualCue":"Rainbow health bowl bursting with textures."}]'::jsonb,
  '"Cornstarch is the single secret to getting tofu as crispy as restaurant fried chicken without deep frying.","Toss the glaze on for only 30 seconds so the tofu retains its crunch."',
  '[{"original":"Tofu","alternative":"Seared salmon cubes or peeled shrimp","notes":"Seafood poke bowl"}]'::jsonb,
  '[{"mistake":"Using soft or silken tofu","remedy":"Only extra-firm pressed tofu holds its shape in the hot skillet."}]'::jsonb,
