  '"Vegetarian","Vegan","Gluten-Free","Dairy-Free","Breakfast","Quick Meals","Under 15 mins","American","Jain-Friendly"',
  '"Blender","Non-stick griddle or skillet","Spatula"',
  '[{"name":"Gluten-free rolled oats","amount":1.5,"unit":"cups","notes":"Blended into flour","category":"Pantry"},{"name":"Ripe spotted banana","amount":1,"unit":"large","notes":"Natural binder & sweetener","category":"Produce"},{"name":"Unsweetened almond milk or oat milk","amount":1,"unit":"cup","notes":"Liquid base","category":"Dairy"},{"name":"Baking powder & ground cinnamon","amount":1.5,"unit":"tsp","notes":"Leavening and aroma","category":"Spices"},{"name":"Fresh blueberries","amount":0.75,"unit":"cup","notes":"Studded into wet batter on pan","category":"Produce"},{"name":"Pure maple syrup","amount":3,"unit":"tbsp","notes":"Warm drizzle","category":"Pantry"}]'::jsonb,
  '[{"step":1,"title":"Blend Batter in 60 Seconds","instruction":"Add oats, banana, plant milk, baking powder, cinnamon, vanilla, and pinch salt to blender. Blend on high for 60 seconds until completely smooth. Rest 3 mins to thicken slightly.","time":"3 mins","temp":"Room temp","visualCue":"Thick, creamy pourable pancake batter."},{"step":2,"title":"Pour onto Griddle & Add Blueberries","instruction":"Heat lightly greased skillet on medium-low. Pour 1/4 cup batter per pancake. Drop fresh blueberries directly onto wet batter surface.","time":"3 mins","temp":"Medium-low heat","visualCue":"Small bubbles form on surface and edges look matte."},{"step":3,"title":"Flip to Golden Puff","instruction":"Flip pancakes and cook for 2 minutes on second side until puffed and golden brown.","time":"2 mins","temp":"Medium-low heat","visualCue":"Puffed golden brown pancakes with bursting purple blueberries."},{"step":4,"title":"Stack & Drizzle Warm Maple","instruction":"Stack hot pancakes high on a plate, top with extra blueberries, and drizzle generously with warm pure maple syrup.","time":"1 min","temp":"Hot","visualCue":"Golden stack dripping with amber maple syrup."}]'::jsonb,
  '"Letting the blended batter rest for 3 minutes allows the oat starches to hydrate, creating thicker, fluffier pancakes.","Press blueberries into the wet batter on the griddle rather than blending them into the batter."',
  '[{"original":"Almond milk","alternative":"Oat milk, soy milk, or dairy milk","notes":"Any milk works"}]'::jsonb,
  '[{"mistake":"Griddle too hot","remedy":"Oat batter browns faster than flour; cook on medium-low for even rise."}]'::jsonb,
  '{}',
