(
  'royal-gulab-jamun-kesar',
  'royal-gulab-jamun-kesar',
  'Shahi Khoya Gulab Jamun in Saffron Rose Syrup',
  'Golden, melt-in-the-mouth mawa dumplings soaked in green cardamom and Kashmiri saffron nectar',
  'The undisputed monarch of Indian celebrations. Fresh reduced whole-milk khoya and chenna are gently kneaded with aromatic mace and cardamom, rolled into seamless spheres, slowly deep-fried in fragrant desi ghee at low heat until a deep mahogany blush, then bathed in warm rose-infused saffron syrup.',
  'Desserts',
  'North Indian',
  '25 mins',
  25,
  '30 mins',
  30,
  '55 mins',
  6,
  'Medium',
  4.98,
  420,
  340,
  '"Desserts","Indian Sweets","Vegetarian","Eggless","Festive","Warm"',
  '"Heavy-bottomed kadai / wok","Slotted frying ladle","Saucepan for sugar syrup"',
  '[{"name":"Fresh mawa / khoya (crumbled)","amount":250,"unit":"g","notes":"Soft whole-milk solid","category":"Dairy"},{"name":"Fresh paneer or chenna","amount":60,"unit":"g","notes":"Finely grated and mashed smooth","category":"Dairy"},{"name":"All-purpose flour (maida)","amount":3,"unit":"tbsp","notes":"For gentle binding","category":"Pantry"},{"name":"Baking soda","amount":0.25,"unit":"tsp","notes":"For pillow-soft lift","category":"Baking"},{"name":"Granulated sugar","amount":400,"unit":"g","notes":"For light one-string syrup","category":"Pantry"},{"name":"Water","amount":350,"unit":"ml","notes":"Syrup base","category":"Pantry"},{"name":"Green cardamom pods","amount":5,"unit":"pods","notes":"Lightly crushed","category":"Spices"},{"name":"Kashmiri saffron threads","amount":15,"unit":"strands","notes":"For golden hue and royal aroma","category":"Spices"},{"name":"Rose water","amount":1,"unit":"tsp","notes":"Edible culinary essence","category":"Flavoring"},{"name":"Pure desi ghee","amount":500,"unit":"ml","notes":"For gentle deep frying","category":"Dairy"}]'::jsonb,
  '[{"step":1,"title":"Brew Saffron Rose Syrup","instruction":"Combine granulated sugar, water, and crushed cardamom in a wide saucepan over medium heat. Bring to an active boil until the sugar fully dissolves. Simmer for 6-7 minutes until the syrup achieves a sticky, half-thread consistency. Stir in saffron strands and rose water, then turn heat to warm.","time":"8 mins","temp":"Medium heat","visualCue":"Syrup coats the back of a spoon with a glossy, light syrupy film"},{"step":2,"title":"Knead Khoya & Chenna Dough","instruction":"On a clean marble surface, grate the khoya and fresh paneer. Use the heel of your palm to smooth and knead for 5 minutes until completely lump-free and silky. Sift in flour and baking soda. Lightly bring together into a soft, pliable dough without overworking.","time":"6 mins","temp":"Room temperature","visualCue":"Dough feels like soft silk with zero grainy granules"},{"step":3,"title":"Shape Seamless Spheres","instruction":"Divide the dough into 18-20 miniature balls (about 15g each). Roll between your palms with gentle pressure until completely smooth without any microscopic surface cracks.","time":"5 mins","temp":"Room temperature","visualCue":"Perfect glass-smooth spheres that will not split during frying"},{"step":4,"title":"Gentle Ghee Frying","instruction":"Heat desi ghee in a heavy kadai to low-medium heat (approx 140°C / 285°F). Slide in dumplings. Swirl the ghee gently around them with a slotted spoon without directly piercing the dumplings. Fry slowly, gently basting as they expand and turn into an even, rich golden mahogany.","time":"10 mins","temp":"Low heat (140°C)","visualCue":"Deep glossy mahogany skin and evenly puffed spherical shapes"},{"step":5,"title":"Warm Syrup Bath","instruction":"Remove with a slotted spoon and immediately immerse the fried dumplings into the warm saffron syrup. Allow them to rest and absorb the fragrant nectar for at least 2 hours before serving warm.","time":"2 hours resting","temp":"Warm syrup","visualCue":"Jamuns double in plumpness and tenderly yield to the touch of a silver spoon"}]'::jsonb,
  '"Never fry in hot oil; low and slow temperature is the secret to thorough cooking through the center.","The syrup must be lukewarm when adding hot dumplings so they drink up the nectar without collapsing."',
  '[{"original":"Mawa / Khoya","substitute":"Milk powder kneaded with warm milk and ghee","notes":"Acceptable pantry backup for quick gulab jamun"}]'::jsonb,
  '[{"mistake":"Frying on high heat","consequence":"The outer crust turns dark brown instantly while the inside remains a dense, uncooked raw dough core."}]'::jsonb,
  '"Dairy","Gluten"',
  'Take care when transferring hot fried dumplings into liquid syrup.',
  'Refrigerate in an airtight glass container in syrup for up to 10 days. Warm gently before eating.',
  'https://images.unsplash.com/photo-1546833999-b9f581a1996d?auto=format&fit=crop&w=1000&q=80',
  false,
  '{"servingSize":"2 gulab jamuns with syrup (~120g)","calories":340,"energyKj":1423,"protein":7,"carbohydrates":54,"sugar":44,"fiber":0.5,"totalFat":12,"saturatedFat":7,"sodium":75}'::jsonb
),
